DG.put("rudr-avtaar/1",{"n":1,"title":"ਅਥ ਰੁਦ੍ਰ ਅਵਤਾਰ ਕਥਨੰ","title_roman":"Ath rudr avtaar kathnan","page":816,"blocks":[{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":816,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":816,"lines":[{"gurmukhi":"ਅਬ ਕਹੋ ਤਉਨ ਸੁਧਾਰਿ। ਜੇ ਧਰੇ ਰੁਦ੍ਰ ਅਵਤਾਰ।","roman":"Ab kaho taun sudhaari | je dhare rudr avtaar |","meaning_en":"Now I tell, setting it out properly, of the forms that Rudra took as incarnations.","page":816,"meaning_status":"draft","note":"ਸੁਧਾਰਿ: 'carefully, properly'."},{"gurmukhi":"ਅਤਿ ਜੋਗ ਸਾਧਨ ਕੀਨ। ਤਬ ਗਰਬ ਕੇ ਰਸਿ ਭੀਨ। ੧।","roman":"Ati jog saadhan keen | tab garab ke rasi bheen | 1 |","meaning_en":"He practised yoga intensely, and then became steeped in the flavour of pride.","page":816,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":816,"lines":[{"gurmukhi":"ਸਰਿ ਆਪ ਜਾਨ ਨ ਅਉਰ। ਸਬ ਦੇਸ ਮੋ ਸਬ ਠੌਰ।","roman":"Sari aap jaan na aur | sab des mo sab thaur |","meaning_en":"He thought no one else his equal, in all lands and in every place.","page":816,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਕੋਪਿ ਕੈ ਇਮ ਕਾਲ। ਇਮ ਭਾਖਿ ਬੈਣ ਉਤਾਲ। ੨।","roman":"Tab kopi kai im kaal | im bhaakhi bain utaal | 2 |","meaning_en":"Then Kal, in anger, spoke these words quickly:","page":816,"meaning_status":"draft","note":"ਕਾਲ: the Lord as Time/Death (Kal); ਉਤਾਲ: 'quickly, at once'."}]},{"type":"verse","number":[3],"number_text":"੩।","page":816,"lines":[{"gurmukhi":"ਜੇ ਗਰਬ ਲੋਕ ਕਰੰਤ। ਤੇ ਜਾਨ ਕੂਪ ਪਰੰਤ।","roman":"Je garab lok karant | te jaan koop parant |","meaning_en":"\"Those people who are proud, know that they fall into a well.","page":816,"meaning_status":"draft"},{"gurmukhi":"ਮੁਰ ਨਾਮ ਗਰਬ ਪ੍ਰਹਾਰ। ਸੁਨ ਲੇਹੁ ਰੁਦ੍ਰ ਬਿਚਾਰ। ੩।","roman":"Mur naam garab prahaar | sun lehu rudr bichaar | 3 |","meaning_en":"My name is Destroyer of Pride; listen, Rudra, and reflect.","page":816,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":816,"lines":[{"gurmukhi":"ਕੀਅ ਗਰਬ ਕੋ ਮੁਖ ਚਾਰ। ਕਛੁ ਚਿਤ ਮੋ ਅਬਿਚਾਰਿ।","roman":"Keea garab ko mukh chaar | kachhu chit mo abichaari |","meaning_en":"The four-faced one (Brahma) was proud, somewhat thoughtless in his mind;","page":816,"meaning_status":"draft","note":"ਮੁਖ ਚਾਰ: Brahma."},{"gurmukhi":"ਜਬ ਧਰੇ ਤਿਨ ਤਨ ਸਾਤ। ਤਬ ਬਨੀ ਤਾ ਕੀ ਬਾਤ। ੪।","roman":"Jab dhare tin tan saat | tab banee taa kee baat | 4 |","meaning_en":"when he took seven bodies, only then did his matter come right.","page":816,"meaning_status":"draft","note":"Refers to Brahma's seven incarnations told elsewhere."}]},{"type":"verse","number":[5],"number_text":"੫।","page":816,"lines":[{"gurmukhi":"ਤਿਮ ਜਨਮੁ ਧਰੁ ਤੈ ਜਾਇ। ਚਿਤ ਦੇ ਸੁਨੋ ਮੁਨਿ ਰਾਇ।","roman":"Tim janmu dharu tai jaai | chit de suno muni raai |","meaning_en":"In the same way you too must go and take birth; listen attentively, king of sages.","page":816,"meaning_status":"draft"},{"gurmukhi":"ਨਹੀ ਐਸ ਹੋਇ ਉਧਾਰ। ਸੁਨ ਲੇਹੁ ਰੁਦ੍ਰ ਬਿਚਾਰ। ੫।","roman":"Nahee ais hoi udhaar | sun lehu rudr bichaar | 5 |","meaning_en":"Otherwise there will be no deliverance; listen, Rudra, and reflect.\"","page":816,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":816,"lines":[{"gurmukhi":"ਸੁਨਿ ਸ੍ਰਵਨ ਏ ਸਿਵ ਬੈਨ। ਹਠ ਛਾਡਿ ਸੁੰਦਰ ਨੈਨ।","roman":"Suni sravan e siv bain | hath chhaadi sundar nain |","meaning_en":"Hearing these words with his ears, Shiva of the beautiful eyes gave up his obstinacy;","page":816,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਜਾਨਿ ਗਰਬ ਪ੍ਰਹਾਰ। ਛਿਤਿ ਲੀਨ ਆਨਿ ਵਤਾਰ। ੬।","roman":"Tih jaani garab prahaar | chhiti leen aani vataar | 6 |","meaning_en":"knowing Him to be the Destroyer of Pride, he came and took incarnation on earth.","page":816,"meaning_status":"draft","note":"ਵਤਾਰ: printed so; read as avtaar."}]},{"type":"heading","kind":"chhand","name":"ਪਾਧਰੀ ਛੰਦ","gurmukhi":"ਪਾਧਰੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"Padhari metre.","page":816,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":816,"lines":[{"gurmukhi":"ਜਿਮ ਕਥੇ ਸਰਬ ਰਾਜਾਨ ਰਾਜ। ਤਿਮ ਕਹੇ ਰਿਖਿਨ ਸਬ ਹੀ ਸਮਾਜ।","roman":"Jim kathe sarab raajaan raaj | tim kahe rikhin sab hee samaaj |","meaning_en":"As the kings of all kings have been told of, so all the company of the sages is told of;","page":816,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਜਿਹ ਪ੍ਰਕਾਰ ਤਿਹ ਕਰਮ ਕੀਨ। ਜਿਹ ਭਾਤਿ ਜੇਮਿ ਦਿਜ ਬਰਨ ਲੀਨ। ੭।","roman":"Jih jih prakaar tih karam keen | jih bhaati jemi dij baran leen | 7 |","meaning_en":"in whatever way he did his deeds, and in what manner he took on the Brahmin caste.","page":816,"meaning_status":"draft","note":"ਜੇਮਿ: 'how'; ਦਿਜ ਬਰਨ: Brahmin varna."}]},{"type":"verse","number":[8],"number_text":"੮।","page":816,"lines":[{"gurmukhi":"ਜੇ ਜੇ ਚਰਿਤ੍ਰ ਕਿਨੇ ਪ੍ਰਕਾਸ। ਤੇ ਤੇ ਚਰਿਤ੍ਰ ਭਾਖੋ ਸੁ ਬਾਸ।","roman":"Je je charitr kine prakaas | te te charitr bhaakho su baas |","meaning_en":"Whatever wondrous deeds he made manifest, those deeds I tell well.","page":816,"meaning_status":"draft","note":"ਸੁ ਬਾਸ: literally 'with good fragrance'; read as 'beautifully'; uncertain."},{"gurmukhi":"ਰਿਖਿ ਪੁਤ੍ਰ ਏਸ ਭਏ ਰੁਦ੍ਰ ਦੇਵ। ਮੋਨੀ ਮਹਾਨ ਮਾਨੀ ਅਭੇਵ। ੮।","roman":"Rikhi putr es bhae rudr dev | monee mahaan maanee abhev | 8 |","meaning_en":"Thus Rudra the god became a sage's son, a great silent sage, honoured and beyond mystery.","page":816,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":816,"lines":[{"gurmukhi":"ਪੁਨਿ ਭਏ ਅਤ੍ਰਿ ਰਿਖਿ ਮੁਨਿ ਮਹਾਨ। ਦਸ ਚਾਰ ਚਾਰ ਬਿਦਿਆ ਨਿਧਾਨ।","roman":"Puni bhae atri rikhi muni mahaan | das chaar chaar bidiaa nidhaan |","meaning_en":"Then there was Atri, the great rishi and sage, treasury of the eighteen branches of learning.","page":816,"meaning_status":"draft","note":"ਦਸ ਚਾਰ ਚਾਰ: 10+4+4 = eighteen (vidyas); some read as fourteen plus four."},{"gurmukhi":"ਲਿਨੇ ਸੁ ਜੋਗ ਤਜਿ ਰਾਜ ਆਨਿ। ਸੇਵਿਆ ਰੁਦ੍ਰ ਸੰਪਤਿ ਨਿਧਾਨ। ੯।","roman":"Line su jog taji raaj aani | seviaa rudr sanpti nidhaan | 9 |","meaning_en":"He took up yoga, abandoning his kingdom, and served Rudra, the treasury of wealth.","page":816,"meaning_status":"draft","note":"ਆਨਿ: 'coming'."}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":817,"lines":[{"gurmukhi":"ਕਿਨੋ ਸੁ ਯੋਗ ਬਹੁ ਦਿਨ ਪ੍ਰਮਾਨ। ਰੀਝਿਓ ਰੁਦ੍ਰ ਤਾ ਪਰ ਨਿਦਾਨ।","roman":"Kino su yog bahu din pramaan | reejhio rudr taa par nidaan |","meaning_en":"He practised yoga for many days; at last Rudra was pleased with him:","page":817,"meaning_status":"draft"},{"gurmukhi":"ਬਰੁ ਮਾਂਗ ਪੁਤ੍ਰ ਜੋ ਰੁਚੈ ਤੋਹਿ। ਬਰੁ ਦਾਨੁ ਤਉਨ ਮੈ ਦੇਉ ਤੋਹਿ। ੧੦।","roman":"Baru maang putr jo ruchai tohi | baru daanu taun mai deu tohi | 10 |","meaning_en":"\"Son, ask for whatever boon pleases you; that boon I will grant you.\"","page":817,"meaning_status":"draft"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":817,"lines":[{"gurmukhi":"ਕਰਿ ਜੋਰਿ ਅਤ੍ਰਿ ਤਬ ਭਯੋ ਠਾਢ। ਉਠਿ ਭਾਗ ਆਨ ਅਨੁਰਾਗ ਬਾਢ।","roman":"Kari jori atri tab bhayo thaadh | uthi bhaag aan anuraag baadh |","meaning_en":"Then Atri stood with joined hands; he rose and ran forward, his love increasing.","page":817,"meaning_status":"draft"},{"gurmukhi":"ਗਦ ਗਦ ਸੁ ਬੈਣ ਭਭਕੰਤ ਨੈਣ। ਰੋਮਾਨ ਹਰਖ ਉਚਰੇ ਸੁ ਬੈਣ। ੧੧।","roman":"Gad gad su bain bhabhkant nain | romaan harakh uchre su bain | 11 |","meaning_en":"With choked voice, eyes brimming, hair standing on end with joy, he spoke these words:","page":817,"meaning_status":"draft","note":"ਭਭਕੰਤ ਨੈਣ: 'eyes welling up'; uncertain."}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":817,"lines":[{"gurmukhi":"ਜੋ ਦੇਤ ਰੁਦ੍ਰ ਬਰੁ ਰੀਝ ਮੋਹਿ। ਗ੍ਰਿਹ ਹੋਇ ਪੁਤ੍ਰ ਸਮ ਤੁਲਿ ਤੋਹਿ।","roman":"Jo det rudr baru reejh mohi | grih hoi putr sam tuli tohi |","meaning_en":"\"If you, Rudra, being pleased, grant me a boon, let a son equal to you be born in my house.\"","page":817,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿ ਕੈ ਤਥਾਸਤੁ ਭਏ ਅੰਤ੍ਰ ਧਿਆਨ। ਗ੍ਰਿਹ ਗਯੋ ਅਤ੍ਰਿ ਮੁਨਿ ਮਨਿ ਮਹਾਨ। ੧੨।","roman":"Kahi kai tathaastu bhae antr dhiaan | grih gayo atri muni mani mahaan | 12 |","meaning_en":"Saying 'So be it', he vanished; the great sage Atri, jewel of sages, went home.","page":817,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":817,"lines":[{"gurmukhi":"ਗ੍ਰਿਹਿ ਬਰੀ ਆਨਿ ਅਨਸੂਆ ਨਾਰਿ। ਜਨੁ ਪਠਿਓ ਤਤੁ ਨਿਜ ਸਿਵ ਨਿਕਾਰਿ।","roman":"Grihi baree aani ansooaa naari | janu pathio tatu nij siv nikaari |","meaning_en":"At home he married a woman named Anasuya, as if Shiva had drawn out his own essence and sent it;","page":817,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਹਮਾ ਰੁ ਬਿਸਨ ਨਿਜ ਤੇਜ ਕਾਢਿ। ਆਏ ਸੁ ਮਧਿ ਅਨਿਸੂਆ ਛਾਡਿ। ੧੩।","roman":"Brahmaa ru bisan nij tej kaadhi | aae su madhi anisooaa chhaadi | 13 |","meaning_en":"Brahma and Vishnu too drew out their own splendour and came and left it in Anasuya.","page":817,"meaning_status":"draft","note":"ਅਨਿਸੂਆ: printed so; Anasuya."}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":817,"lines":[{"gurmukhi":"ਭਈ ਕਰਤ ਜੋਗ ਬਹੁ ਦਿਨ ਪ੍ਰਮਾਨ। ਅਨਸੂਆ ਨਾਮ ਗੁਨ ਗਨ ਮਹਾਨ।","roman":"Bhaee karat jog bahu din pramaan | ansooaa naam gun gan mahaan |","meaning_en":"She had done yoga for many days; Anasuya by name, great in all virtues,","page":817,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਤੇਜਵੰਤ ਸੋਭਾ ਸੁਰੰਗ। ਜਨੁ ਧਰਾ ਰੂਪ ਦੂਸਰ ਅਨੰਗ। ੧੪।","roman":"Ati tejvant sobhaa surang | janu dharaa roop doosar anang | 14 |","meaning_en":"very radiant, of beautiful glory, as if a second Anang (Kama) had taken form.","page":817,"meaning_status":"draft","note":"ਅਨੰਗ: Kama, the god of love."}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":817,"lines":[{"gurmukhi":"ਸੋਭਾ ਅਪਾਰ ਸੁੰਦਰ ਅਨੰਤ। ਸਊਹਾਗ ਭਾਗ ਬਹੁ ਬਿਧਿ ਲਸੰਤ।","roman":"Sobhaa apaar sundar anant | saoohaag bhaag bahu bidhi lasant |","meaning_en":"Her beauty boundless, her loveliness endless; fortune and happy wifehood shone on her in many ways.","page":817,"meaning_status":"draft","note":"ਸਊਹਾਗ: suhaag, married good fortune."},{"gurmukhi":"ਜਿਹ ਨਿਰਖਿ ਰੂਪ ਸੋਰਹਿ ਲੁਭਾਇ। ਆਭਾ ਅਪਾਰ ਬਰਨੀ ਨ ਜਾਇ। ੧੫।","roman":"Jih nirkhi roop sorhi lubhaai | aabhaa apaar barnee na jaai | 15 |","meaning_en":"Seeing her form, even the sixteen were enchanted; her boundless radiance cannot be described.","page":817,"meaning_status":"draft","note":"ਸੋਰਹਿ: 'sixteen' — perhaps the sixteen adornments or sixteen phases of the moon; uncertain."}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":817,"lines":[{"gurmukhi":"ਨਿਸ ਨਾਥ ਦੇਖਿ ਆਨਨ ਰਿਸਾਨ। ਜਲਿ ਜਾਇ ਨੈਨ ਲਹਿ ਰੋਸ ਮਾਨ।","roman":"Nis naath dekhi aanan risaan | jali jaai nain lahi ros maan |","meaning_en":"The lord of the night (the moon), seeing her face, grew angry; seeing her eyes he burned with rage.","page":817,"meaning_status":"draft","note":"Second half uncertain: 'seeing her eyes (the lotuses?) burn with jealousy'."},{"gurmukhi":"ਤਮ ਨਿਰਖਿ ਕੇਸ ਕੀਅ ਨੀਚ ਡੀਠ। ਛਪਿ ਰਹਾ ਜਾਨੁ ਗਿਰ ਹੇਮ ਪੀਠ। ੧੬।","roman":"Tam nirkhi kes keea neech deeth | chhapi rahaa jaanu gir hem peeth | 16 |","meaning_en":"Darkness, seeing her hair, cast its eyes down, and hid itself as if behind the golden mountain.","page":817,"meaning_status":"draft","note":"ਗਿਰ ਹੇਮ: Mount Sumeru (golden mountain); ਪੀਠ: 'back'."}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":817,"lines":[{"gurmukhi":"ਕੰਠਹਿ ਕਪੋਤਿ ਲਖਿ ਕੋਪ ਕੀਨ। ਨਾਸਾ ਨਿਹਾਰਿ ਬਨਿ ਕੀਰ ਲੀਨ।","roman":"Kanthhi kapoti lakhi kop keen | naasaa nihaari bani keer leen |","meaning_en":"The female dove grew angry seeing her throat; the parrot, seeing her nose, took to the forest.","page":817,"meaning_status":"draft"},{"gurmukhi":"ਰੋਮਾਵਲਿ ਹੇਰਿ ਜਮੁਨਾ ਰਿਸਾਨ। ਲਜਾ ਮਰੰਤ ਸਾਗਰ ਡੁਬਾਨ। ੧੭।","roman":"Romaavli heri jamunaa risaan | lajaa marant saagar dubaan | 17 |","meaning_en":"The Yamuna, seeing the line of hair on her body, grew angry; the ocean, dying of shame, sank down.","page":817,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":817,"lines":[{"gurmukhi":"ਬਾਹੂ ਬਿਲੋਕਿ ਲਾਜੈ ਮ੍ਰਿਨਾਲ। ਖਿਸਿਯਾਨ ਹੰਸ ਅਵਿਲੋਕਿ ਚਾਲ।","roman":"Baahoo biloki laajai mrinaal | khisiyaan hans aviloki chaal |","meaning_en":"Seeing her arms, the lotus stalk is ashamed; seeing her gait, the swan is abashed.","page":817,"meaning_status":"draft"},{"gurmukhi":"ਜੰਘਾ ਬਿਲੋਕਿ ਕਦਲੀ ਲਜਾਨ। ਨਿਸ ਰਾਟ ਆਪ ਘਟਿ ਰੂਪ ਮਾਨ। ੧੮।","roman":"Janghaa biloki kadlee lajaan | nis raat aap ghati roop maan | 18 |","meaning_en":"Seeing her thighs, the plantain is ashamed; the king of night (moon) thinks his own beauty lessened.","page":817,"meaning_status":"draft"}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":817,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਤਾਸੁ ਬਰਣੋ ਸਿੰਗਾਰ। ਕੋ ਸਕੈ ਕਬਿ ਮਹਿਮਾ ਉਚਾਰ।","roman":"Ih bhaati taasu barno singaar | ko sakai kabi mahimaa uchaar |","meaning_en":"In this way her adornment is described; what poet can tell her glory?","page":817,"meaning_status":"draft"},{"gurmukhi":"ਐਸੀ ਸਰੂਪ ਅਵਿਲੋਕ ਅਤ੍ਰਿ। ਜਨੁ ਲੀਨ ਰੂਪ ਕੋ ਛੀਨ ਛਤ੍ਰ। ੧੯।","roman":"Aisee saroop avilok atri | janu leen roop ko chheen chhatr | 19 |","meaning_en":"Atri saw her of such beauty, as if she had snatched the canopy of beauty itself.","page":817,"meaning_status":"draft","note":"ਛਤ੍ਰ: canopy, symbol of sovereignty."}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":817,"lines":[{"gurmukhi":"ਕੀਨੀ ਪ੍ਰਤਗਿ ਤਿਹ ਸਮੇ ਨਾਰਿ। ਬ੍ਯਾਹੈ ਨ ਭੋਗ ਭੋਗੈ ਭਤਾਰ।","roman":"Keenee pratgi tih same naari | byaahai na bhog bhogai bhataar |","meaning_en":"At that time the woman made a vow: \"I will not marry a husband who enjoys pleasures;","page":817,"meaning_status":"draft","note":"Sense uncertain: 'a husband who would marry and enjoy indulgence'."},{"gurmukhi":"ਮੈ ਬਰੌ ਤਾਸੁ ਰੁਚਿ ਮਾਨਿ ਚਿਤ। ਜੋ ਸਹੈ ਕਸਟ ਐਸੇ ਪਵਿਤ। ੨੦।","roman":"Mai barau taasu ruchi maani chit | jo sahai kasat aise pavit | 20 |","meaning_en":"I will marry, gladly, that pure one who endures such hardship.\"","page":817,"meaning_status":"draft"}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":818,"lines":[{"gurmukhi":"ਰਿਖਿ ਮਾਨਿ ਬੈਨ ਤਬ ਬਰ੍ਯੋ ਵਾਹਿ। ਜਨੁ ਲੀਨ ਲੂਟ ਸੀਗਾਰ ਤਾਹਿ।","roman":"Rikhi maani bain tab baryo vaahi | janu leen loot seegaar taahi |","meaning_en":"The rishi accepted her words and then married her, as if he had carried off all adornment.","page":818,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਗਯੋ ਧਾਮਿ ਕਰਿ ਨਾਰਿ ਤਉਨ। ਪਿਤ ਦਤ ਦੇਵ ਮੁਨਿ ਅਤ੍ਰਿ ਜਉਨ। ੨੧।","roman":"Lai gayo dhaami kari naari taun | pit dat dev muni atri jaun | 21 |","meaning_en":"He took her home as his wife — Atri the sage, who was to be the father of Datt the divine.","page":818,"meaning_status":"draft"}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਰੁਦ੍ਰ ਵਤਾਰ ਦਤ ਕਥਨੰ","gurmukhi":"ਅਥ ਰੁਦ੍ਰ ਵਤਾਰ ਦਤ ਕਥਨੰ","roman":"Ath rudr vataar dat kathnan","meaning_en":"Now begins the account of Datt, the incarnation of Rudra.","page":818,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":818,"meaning_status":"draft"},{"type":"verse","number":[22],"number_text":"੨੨।","page":818,"lines":[{"gurmukhi":"ਬਹੁ ਬਰਖ ਬੀਤ ਕਿਨੋ ਬਿਵਾਹਿ। ਇਕ ਭਯੋ ਆਨਿ ਅਉਰੈ ਉਛਾਹਿ।","roman":"Bahu barakh beet kino bivaahi | ik bhayo aani aurai uchhaahi |","meaning_en":"Many years passed after the marriage; then came another occasion of joy.","page":818,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਗਏ ਧਾਮਿ ਬ੍ਰਹਮਾਦਿ ਆਦਿ। ਕਿਨੀ ਸੁ ਸੇਵ ਤ੍ਰੀਯ ਬਹੁ ਪ੍ਰਸਾਦਿ। ੨੨।","roman":"Tih gae dhaami brahmaadi aadi | kinee su sev treey bahu prasaadi | 22 |","meaning_en":"Brahma and the other gods went to their home; the wife served them well and they were much pleased.","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":818,"lines":[{"gurmukhi":"ਬਹੁ ਧੂਪ ਦੀਪ ਅਰੁ ਅਰਘ ਦਾਨ। ਪਾਦਰਘਿ ਆਦਿ ਕਿਨੇ ਸੁਜਾਨ।","roman":"Bahu dhoop deep aru aragh daan | paadarghi aadi kine sujaan |","meaning_en":"With much incense, lamps and offerings of water, the wise woman washed their feet and did the rest of the rites.","page":818,"meaning_status":"draft","note":"ਪਾਦਰਘਿ: water for washing feet."},{"gurmukhi":"ਅਵਿਲੋਕਿ ਭਗਤਿ ਤਿਹ ਚਤੁਰ ਬਾਕ। ਇੰਦ੍ਰਾਦਿ ਬਿਸਨੁ ਬੈਠੇ ਪਿਨਾਕ। ੨੩।","roman":"Aviloki bhagti tih chatur baak | indraadi bisnu baithe pinaak | 23 |","meaning_en":"Seeing her devotion and clever speech, Indra and the others, Vishnu and Shiva sat there.","page":818,"meaning_status":"draft","note":"ਪਿਨਾਕ: the bow of Shiva, here Shiva; ਚਤੁਰ ਬਾਕ could also mean 'four-mouthed' (Brahma); uncertain."}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":818,"lines":[{"gurmukhi":"ਅਵਿਲੋਕਿ ਭਗਤਿ ਭਏ ਰਿਖ ਪ੍ਰਸੰਨ। ਜੋ ਤਿਹੂ ਮਧਿ ਲੋਕਾਨਿ ਧਨਿ।","roman":"Aviloki bhagti bhae rikh prasann | jo tihoo madhi lokaani dhani |","meaning_en":"Seeing her devotion, the sages were pleased, she who was blessed in all three worlds.","page":818,"meaning_status":"draft"},{"gurmukhi":"ਕਿਨੋ ਸੁ ਐਸ ਬ੍ਰਹਮਾ ਉਚਾਰ। ਤੈ ਪੁਤ੍ਰਵੰਤ ਹੂਜੋ ਕੁਮਾਰਿ। ੨੪।","roman":"Kino su ais brahmaa uchaar | tai putravant hoojo kumaari | 24 |","meaning_en":"Brahma spoke thus: \"Maiden, may you be blessed with sons.\"","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":818,"lines":[{"gurmukhi":"ਕੀਅ ਐਸ ਬ੍ਰਹਮਾ ਉਚਾਰ। ਤੈ ਪੁਤ੍ਰ ਪਾਵਸ ਬਾਰ।","roman":"Keea ais brahmaa uchaar | tai putr paavas baar |","meaning_en":"Brahma said this: \"You will obtain a son soon.\"","page":818,"meaning_status":"draft","note":"ਪਾਵਸ ਬਾਰ: 'without delay'; uncertain."},{"gurmukhi":"ਤਬਿ ਨਾਰਿ ਏ ਸੁਨ ਬੈਨ। ਬਹੁ ਆਸੁ ਡਾਰਤ ਨੈਨ। ੨੫।","roman":"Tabi naari e sun bain | bahu aasu daarat nain | 25 |","meaning_en":"Then the woman, hearing these words, shed many tears from her eyes.","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":818,"lines":[{"gurmukhi":"ਤਬ ਬਾਲ ਬਿਕਲ ਸਰੀਰ। ਜਲ ਸ੍ਰਵਤ ਨੈਨ ਅਧੀਰ।","roman":"Tab baal bikal sareer | jal sravat nain adheer |","meaning_en":"Then the young woman, her body distressed, water flowing from her eyes, restless,","page":818,"meaning_status":"draft"},{"gurmukhi":"ਰੋਮਾਂਚਿ ਗਦ ਗਦ ਬੈਨ। ਦਿਨ ਤੇ ਭਈ ਜਨੁ ਰੈਨ। ੨੬।","roman":"Romaanchi gad gad bain | din te bhaee janu rain | 26 |","meaning_en":"hair on end, voice choked — as if day had turned to night for her.","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":818,"lines":[{"gurmukhi":"ਰੋਮਾਂਚਿ ਬਿਕਲ ਸਰੀਰ। ਤਨ ਕੋਪ ਮਾਨ ਅਧੀਰ।","roman":"Romaanchi bikal sareer | tan kop maan adheer |","meaning_en":"Hair on end, body distressed, her body full of anger, restless,","page":818,"meaning_status":"draft"},{"gurmukhi":"ਫਰਕੰਤ ਉਸਟਰੁ ਨੈਨ। ਬਿਨੁ ਬੁਧ ਬੋਲਤ ਬੈਨ। ੨੭।","roman":"Pharkant usatru nain | binu budh bolat bain | 27 |","meaning_en":"her lips and eyes quivering, she spoke words without thought.","page":818,"meaning_status":"draft","note":"ਉਸਟਰੁ: read as 'lips'."}]},{"type":"heading","kind":"chhand","name":"ਮੋਹਣ ਛੰਦ","gurmukhi":"ਮੋਹਣ ਛੰਦ","roman":"Mohan chhand","meaning_en":"Mohan metre.","page":818,"meaning_status":"draft"},{"type":"verse","number":[28],"number_text":"੨੮।","page":818,"lines":[{"gurmukhi":"ਸੁਨਿ ਐਸ ਬੈਨ। ਮ੍ਰਿਗੀਏਸ ਨੈਨ। ਅਤਿ ਰੂਪ ਧਾਮ। ਸੁੰਦਰ ਸੁ ਬਾਮ। ੨੮।","roman":"Suni ais bain | mrigee'es nain | ati roop dhaam | sundar su baam | 28 |","meaning_en":"Hearing such words, the doe-eyed one, home of great beauty, the lovely woman,","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":818,"lines":[{"gurmukhi":"ਚਲ ਚਾਲ ਚਿਤ। ਪਰਮੰ ਪਵਿਤ। ਅਤਿ ਕੋਪ ਵੰਤ। ਮੁਨਿ ਤ੍ਰਿਅ ਬਿਅੰਤ। ੨੯।","roman":"Chal chaal chit | parman pavit | ati kop vant | muni tria biant | 29 |","meaning_en":"her mind shaken, supremely pure, very angry — the sage's wife without bound —","page":818,"meaning_status":"draft","note":"ਬਿਅੰਤ: 'boundless' (in anger or virtue); uncertain."}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":818,"lines":[{"gurmukhi":"ਉਪਟੰਤ ਕੇਸ। ਮੁਨਿ ਤ੍ਰਿਅ ਸੁਦੇਸ। ਅਤਿ ਕੋਪ ਅੰਗਿ। ਸੁੰਦਰ ਸੁਰੰਗ। ੩੦।","roman":"Uptant kes | muni tria sudes | ati kop angi | sundar surang | 30 |","meaning_en":"tore her hair, the sage's fine wife, her limbs full of anger, beautiful and fair;","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":818,"lines":[{"gurmukhi":"ਤੋਰੰਤ ਹਾਰ। ਉਪਟੰਤ ਬਾਰ। ਡਾਰੰਤ ਧੂਰਿ। ਰੋਖੰਤ ਪੂਰ। ੩੧।","roman":"Torant haar | uptant baar | daarant dhoori | rokhant poor | 31 |","meaning_en":"she broke her necklaces, tore her hair, threw dust on herself, full of rage.","page":818,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":818,"meaning_status":"draft"},{"type":"verse","number":[32],"number_text":"੩੨।","page":818,"lines":[{"gurmukhi":"ਲਖਿ ਕੋਪ ਭੀ ਮੁਨਿ ਨਾਰਿ। ਉਠਿ ਭਾਜ ਬ੍ਰਹਮ ਉਦਾਰ।","roman":"Lakhi kop bhee muni naari | uthi bhaaj braham udaar |","meaning_en":"Seeing the sage's wife angered, the generous Brahma rose and fled;","page":818,"meaning_status":"draft"},{"gurmukhi":"ਸਿਵ ਸੰਗਿ ਲੈ ਰਿਖ ਸਰਬ। ਭਯਮਾਨ ਹ੍ਵੈ ਤਜਿ ਗਰਬ। ੩੨।","roman":"Siv sangi lai rikh sarab | bhaymaan hvai taji garab | 32 |","meaning_en":"taking Shiva and all the rishis with him, frightened, his pride abandoned.","page":818,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":819,"lines":[{"gurmukhi":"ਤਬ ਕੋਪ ਕੈ ਮੁਨਿ ਨਾਰਿ। ਸਿਰ ਕੇਸ ਜਟਾ ਉਪਾਰਿ।","roman":"Tab kop kai muni naari | sir kes jataa upaari |","meaning_en":"Then the sage's wife in anger tore out the matted locks of hair from her head;","page":819,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਸੌ ਜਬੈ ਕਰ ਮਾਰ। ਤਬ ਲੀਨ ਦਤ ਅਵਤਾਰ। ੩੩।","roman":"Kari sau jabai kar maar | tab leen dat avtaar | 33 |","meaning_en":"when she struck one hand on the other, then Datt took incarnation.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":819,"lines":[{"gurmukhi":"ਕਰ ਬਾਮ ਮਾਤ੍ਰ ਸਮਾਨ। ਕਰੁ ਦਛਨਤ੍ਰਿ ਪ੍ਰਮਾਨ।","roman":"Kar baam maatr samaan | karu dachhantri pramaan |","meaning_en":"The left hand being like the mother and the right hand like Atri,","page":819,"meaning_status":"draft","note":"ਦਛਨਤ੍ਰਿ: read as 'dachhan (right) = Atri'; uncertain."},{"gurmukhi":"ਕੀਆ ਪਾਨ ਭੋਗ ਬਿਚਾਰ। ਤਬ ਭਏ ਦਤ ਕੁਮਾਰ। ੩੪।","roman":"Keeaa paan bhog bichaar | tab bhae dat kumaar | 34 |","meaning_en":"the hands joined as in union; then Prince Datt came into being.","page":819,"meaning_status":"draft","note":"ਪਾਨ ਭੋਗ: 'union of hands'; uncertain."}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":819,"lines":[{"gurmukhi":"ਅਨਭੂਤ ਉਤਮ ਗਾਤ। ਉਚਰੰਤ ਸਿੰਮ੍ਰਿਤ ਸਾਤ।","roman":"Anbhoot utam gaat | uchrant sinmrit saat |","meaning_en":"Of wonderful, excellent body, reciting the seven Smritis,","page":819,"meaning_status":"draft"},{"gurmukhi":"ਮੁਖਿ ਬੇਦ ਚਾਰ ਰੜੰਤ। ਉਪਜੋ ਸੁ ਦਤ ਮਹੰਤ। ੩੫।","roman":"Mukhi bed chaar rarant | upjo su dat mahant | 35 |","meaning_en":"repeating the four Vedas with his mouth — so the great Datt was born.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":819,"lines":[{"gurmukhi":"ਸਿਵ ਸਿਮਰਿ ਪੂਰਬਲ ਸ੍ਰਾਪ। ਬਪੁ ਦਤ ਕੋ ਧਰਿ ਆਪ।","roman":"Siv simri poorbal sraap | bapu dat ko dhari aap |","meaning_en":"Shiva, remembering the earlier curse, himself took on the body of Datt,","page":819,"meaning_status":"draft"},{"gurmukhi":"ਉਪਜਿਓਨਿਸੂਆ ਧਾਮਿ। ਅਵਤਾਰ ਪ੍ਰਿਥਮ ਸੁ ਤਾਮ। ੩੬।","roman":"Upjionisooaa dhaami | avtaar pritham su taam | 36 |","meaning_en":"and was born in Anasuya's house; that was the first incarnation.","page":819,"meaning_status":"draft","note":"ਉਪਜਿਓਨਿਸੂਆ: printed so; read as upjio Anasuya."}]},{"type":"heading","kind":"chhand","name":"ਪਾਧਰੀ ਛੰਦ","gurmukhi":"ਪਾਧਰੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"Padhari metre.","page":819,"meaning_status":"draft"},{"type":"verse","number":[37],"number_text":"੩੭।","page":819,"lines":[{"gurmukhi":"ਉਪਜਿਓ ਸੁ ਦਤ ਮੋਨੀ ਮਹਾਨ। ਦਸ ਚਾਰ ਚਾਰ ਬਿਦਿਆ ਨਿਧਾਨ।","roman":"Upjio su dat monee mahaan | das chaar chaar bidiaa nidhaan |","meaning_en":"So was born Datt, the great silent sage, treasury of the eighteen branches of learning,","page":819,"meaning_status":"draft"},{"gurmukhi":"ਸਾਸਤ੍ਰਗਿ ਸੁਧ ਸੁੰਦਰ ਸਰੂਪ। ਅਵਧੂਤ ਰੂਪ ਗਣ ਸਰਬ ਭੂਪ। ੩੭।","roman":"Saastragi sudh sundar saroop | avdhoot roop gan sarab bhoop | 37 |","meaning_en":"knower of the Shastras, pure, of beautiful form, an Avadhut in form, lord of all the hosts.","page":819,"meaning_status":"draft","note":"ਗਣ ਸਰਬ ਭੂਪ: 'king over all the ganas'; uncertain."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":819,"lines":[{"gurmukhi":"ਸੰਨਿਆਸ ਜੋਗ ਕਿਨੋ ਪ੍ਰਕਾਸ। ਪਾਵਨ ਪਵਿਤ ਸਰਬਤ੍ਰ ਦਾਸ।","roman":"Sanniaas jog kino prakaas | paavan pavit sarbatr daas |","meaning_en":"He made manifest the yoga of renunciation (sannyas), holy and pure, servant of all,","page":819,"meaning_status":"draft"},{"gurmukhi":"ਜਨ ਧਰਿਓ ਆਨਿ ਬਪੁ ਸਰਬ ਜੋਗ। ਤਜਿ ਰਾਜ ਸਾਜ ਅਰੁ ਤਿਆਗ ਭੋਗ। ੩੮।","roman":"Jan dhario aani bapu sarab jog | taji raaj saaj aru tiaag bhog | 38 |","meaning_en":"as if the whole of yoga had come and taken a body, abandoning kingly array and giving up pleasures.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":819,"lines":[{"gurmukhi":"ਆਛਿਜ ਰੂਪ ਮਹਿਮਾ ਮਹਾਨ। ਦਸ ਚਾਰਵੰਤ ਸੋਭਾ ਨਿਧਾਨ।","roman":"Aachhij roop mahimaa mahaan | das chaarvant sobhaa nidhaan |","meaning_en":"Of indestructible form, great in glory, possessing the fourteen (lores), treasury of splendour,","page":819,"meaning_status":"draft","note":"ਦਸ ਚਾਰਵੰਤ: 'possessing the fourteen' (vidyas)."},{"gurmukhi":"ਰਵਿ ਅਨਿਲ ਤੇਜ ਜਲ ਸੋ ਸੁਭਾਵ। ਉਪਜਿਆ ਜਗਤ ਸੰਨ੍ਯਾਸ ਰਾਵ। ੩੯।","roman":"Ravi anil tej jal so subhaav | upjiaa jagat sannyaas raav | 39 |","meaning_en":"of a nature like sun, wind, fire and water — the king of renunciates was born into the world.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":819,"lines":[{"gurmukhi":"ਸੰਨ੍ਯਾਸ ਰਾਜ ਭਏ ਦਤ ਦੇਵ। ਰੁਦ੍ਰਾਵਤਾਰ ਸੁੰਦਰ ਅਜੇਵ।","roman":"Sannyaas raaj bhae dat dev | rudraavtaar sundar ajev |","meaning_en":"Datt the divine became the king of sannyasis, the beautiful, invincible incarnation of Rudra,","page":819,"meaning_status":"draft"},{"gurmukhi":"ਪਾਵਕ ਸਮਾਨ ਭਯੇ ਤੇਜ ਜਾਸੁ। ਬਸੁਧਾ ਸਮਾਨ ਧੀਰਜ ਸੁ ਤਾਸੁ। ੪੦।","roman":"Paavak samaan bhaye tej jaasu | basudhaa samaan dheeraj su taasu | 40 |","meaning_en":"whose splendour was like fire, and whose patience was like the earth.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":819,"lines":[{"gurmukhi":"ਪਰਮੰ ਪਵਿਤ੍ਰ ਭਏ ਦੇਵ ਦਤ। ਆਛਿਜ ਤੇਜ ਅਰੁ ਬਿਮਲ ਮਤਿ।","roman":"Parman pavitr bhae dev dat | aachhij tej aru bimal mati |","meaning_en":"Datt the divine was supremely pure, of indestructible splendour and spotless mind.","page":819,"meaning_status":"draft"},{"gurmukhi":"ਸੋਵਰਣ ਦੇਖਿ ਲਾਜੰਤ ਅੰਗ। ਸੋਭੰਤ ਸੀਸ ਗੰਗਾ ਤਰੰਗ। ੪੧।","roman":"Sovran dekhi laajant ang | sobhant sees gangaa tarang | 41 |","meaning_en":"Gold, seeing his limbs, is ashamed; on his head the waves of the Ganga shine.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":819,"lines":[{"gurmukhi":"ਆਜਾਨ ਬਾਹੁ ਅਲਿਪਤ ਰੂਪ। ਆਦਗ ਜੋਗ ਸੁੰਦਰ ਸਰੂਪ।","roman":"Aajaan baahu alipat roop | aadag jog sundar saroop |","meaning_en":"Arms reaching to his knees, of untainted form, the primal yogi, of beautiful form,","page":819,"meaning_status":"draft","note":"ਆਦਗ: read as 'aadi' (primal); uncertain."},{"gurmukhi":"ਬਿਭੂਤ ਅੰਗ ਉਜਲ ਸੁ ਬਾਸ। ਸੰਨਿਆਸ ਜੋਗ ਕਿਨੋ ਪ੍ਰਕਾਸ। ੪੨।","roman":"Bibhoot ang ujal su baas | sanniaas jog kino prakaas | 42 |","meaning_en":"ash on his limbs, bright and fragrant; he made manifest the yoga of renunciation.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":819,"lines":[{"gurmukhi":"ਅਵਿਲੋਕਿ ਅੰਗ ਮਹਿਮਾ ਅਪਾਰ। ਸੰਨਿਆਸ ਰਾਜ ਉਪਜਾ ਉਦਾਰ।","roman":"Aviloki ang mahimaa apaar | sanniaas raaj upjaa udaar |","meaning_en":"Seeing the boundless glory of his body — the noble king of sannyasis was born —","page":819,"meaning_status":"draft"},{"gurmukhi":"ਅਨਭੂਤ ਗਾਤ ਆਭਾ ਅਨੰਤ। ਮੋਨੀ ਮਹਾਨ ਸੋਭਾ ਲਸੰਤ। ੪੩।","roman":"Anbhoot gaat aabhaa anant | monee mahaan sobhaa lasant | 43 |","meaning_en":"wondrous body, endless radiance, the great silent sage shone in beauty.","page":819,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":820,"lines":[{"gurmukhi":"ਆਭਾ ਅਪਾਰ ਮਹਿਮਾ ਅਨੰਤ। ਸੰਨ੍ਯਾਸ ਰਾਜ ਕਿਨੋ ਬਿਅੰਤ।","roman":"Aabhaa apaar mahimaa anant | sannyaas raaj kino biant |","meaning_en":"Boundless radiance, endless glory: he established a boundless reign of renunciation.","page":820,"meaning_status":"draft"},{"gurmukhi":"ਕਾਂਪਿਆ ਕਪਟੁ ਤਿਹ ਉਦੇ ਹੋਤ। ਤਤ ਛਿਨ ਅਕਪਟ ਕਿਨੋ ਉਦੋਤ। ੪੪।","roman":"Kaanpiaa kaptu tih ude hot | tat chhin akpat kino udot | 44 |","meaning_en":"Deceit trembled at his rising; at once he made sincerity shine forth.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":820,"lines":[{"gurmukhi":"ਮਹਿਮਾ ਅਛਿਜ ਅਨਭੂਤ ਗਾਤ। ਆਵਿਲੋਕਿ ਪੁਤ੍ਰ ਚਕਿ ਰਹੀ ਮਾਤ।","roman":"Mahimaa achhij anbhoot gaat | aaviloki putr chaki rahee maat |","meaning_en":"Of indestructible glory and wondrous body; seeing her son, the mother was astonished.","page":820,"meaning_status":"draft"},{"gurmukhi":"ਦੇਸਨ ਬਿਦੇਸ ਚਕਿ ਰਹੀ ਸਰਬ। ਸੁਨਿ ਸਰਬ ਰਿਖਿਨ ਤਜਿ ਦੀਨ ਗਰਬ। ੪੫।","roman":"Desan bides chaki rahee sarab | suni sarab rikhin taji deen garab | 45 |","meaning_en":"All lands, near and far, were astonished; hearing of it, all the rishis gave up their pride.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":820,"lines":[{"gurmukhi":"ਸਰਬਤ੍ਰ ਪ੍ਯਾਲ ਸਰਬਤ੍ਰ ਅਕਾਸ। ਚਲ ਚਾਲ ਚਿਤੁ ਸੁੰਦਰ ਸੁ ਬਾਸ।","roman":"Sarbatr pyaal sarbatr akaas | chal chaal chitu sundar su baas |","meaning_en":"Everywhere in the underworld, everywhere in the sky, minds were stirred by his fair fame;","page":820,"meaning_status":"draft","note":"ਚਲ ਚਾਲ ਚਿਤੁ: 'minds became restless'; ਸੁ ਬਾਸ: fragrance/fame; uncertain."},{"gurmukhi":"ਕੰਪਾਇਮਾਨ ਹਰਖੰਤ ਰੋਮ। ਆਨੰਦਮਾਨ ਸਭ ਭਈ ਭੋਮ। ੪੬।","roman":"Kanpaaimaan harkhant rom | aanandmaan sabh bhaee bhom | 46 |","meaning_en":"hair stood on end with joy and trembling, and all the earth was filled with bliss.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":820,"lines":[{"gurmukhi":"ਥਰਹਰਤ ਭੂਮਿ ਆਕਾਸ ਸਰਬ। ਜਹ ਤਹ ਰਿਖੀਨ ਤਜਿ ਦੀਨ ਗਰਬ।","roman":"Tharahrat bhoomi aakaas sarab | jah tah rikheen taji deen garab |","meaning_en":"The earth and all the sky trembled; everywhere the rishis gave up their pride.","page":820,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜੇ ਬਜੰਤ੍ਰ ਅਨੇਕ ਗੈਨ। ਦਸ ਦਿਉਸ ਪਾਇ ਦਿਖੀ ਨ ਰੈਣ। ੪੭।","roman":"Baaje bajantr anek gain | das dius paai dikhee na rain | 47 |","meaning_en":"Many instruments played in the sky; for ten days no night was seen.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":820,"lines":[{"gurmukhi":"ਜਹ ਤਹ ਬਜੰਤ੍ਰ ਬਾਜੇ ਅਨੇਕ। ਪ੍ਰਗਟਿਆ ਜਾਣੁ ਬਪੁ ਧਰਿ ਬਿਬੇਕ।","roman":"Jah tah bajantr baaje anek | pragtiaa jaanu bapu dhari bibek |","meaning_en":"Everywhere many instruments played; it was as if Discernment had appeared, taking a body.","page":820,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਾ ਅਪਾਰ ਬਰਨੀ ਨ ਜਾਇ। ਉਪਜਿਆ ਆਨ ਸੰਨ੍ਯਾਸ ਰਾਇ। ੪੮।","roman":"Sobhaa apaar barnee na jaai | upjiaa aan sannyaas raai | 48 |","meaning_en":"His boundless beauty cannot be described; the king of sannyasis had come and been born.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":820,"lines":[{"gurmukhi":"ਜਨਮੰਤ ਲਾਗਿ ਉਠ ਜੋਗ ਕਰਮ। ਹਤਿ ਕੀਓ ਪਾਪ ਪਰਚੁਰਿਓ ਧਰਮ।","roman":"Janmant laagi uth jog karam | hati keeo paap parchurio dharam |","meaning_en":"From birth he began the work of yoga; he destroyed sin and spread righteousness.","page":820,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਾਧਿਰਾਜ ਬਡ ਲਾਗ ਚਰਨ। ਸੰਨਿਆਸ ਜੋਗ ਉਠਿ ਲਾਗ ਕਰਨ। ੪੯।","roman":"Raajaadhiraaj bad laag charan | sanniaas jog uthi laag karan | 49 |","meaning_en":"Great kings of kings fell at his feet and began to practise the yoga of renunciation.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":820,"lines":[{"gurmukhi":"ਅਤਿਭੁਤਿ ਅਨੂਪ ਲਖਿ ਦਤ ਰਾਇ। ਉਠਿ ਲਗੇ ਪਾਇ ਨ੍ਰਿਪ ਸਰਬ ਆਇ।","roman":"Atibhuti anoop lakhi dat raai | uthi lage paai nrip sarab aai |","meaning_en":"Seeing King Datt, wondrous and incomparable, all the kings came and fell at his feet,","page":820,"meaning_status":"draft"},{"gurmukhi":"ਅਵਿਲੋਕਿ ਦਤ ਮਹਿਮਾ ਮਹਾਨ। ਦਸ ਚਾਰ ਚਾਰ ਬਿਦਿਆ ਨਿਧਾਨ। ੫੦।","roman":"Aviloki dat mahimaa mahaan | das chaar chaar bidiaa nidhaan | 50 |","meaning_en":"seeing the great glory of Datt, treasury of the eighteen branches of learning.","page":820,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":820,"lines":[{"gurmukhi":"ਸੋਭੰਤ ਸੀਸ ਜਤ ਕੀ ਜਟਾਨ। ਨਖ ਨੇਮ ਕੇ ਸੁ ਬਢਏ ਮਹਾਨ।","roman":"Sobhant sees jat kee jataan | nakh nem ke su badhae mahaan |","meaning_en":"On his head shone matted locks of continence; the nails of his discipline had grown great.","page":820,"meaning_status":"draft","note":"ਨਖ ਨੇਮ ਕੇ: 'nails grown as a vow'."},{"gurmukhi":"ਬਿਭ੍ਰਮ ਬਿਭੂਤ ਉਜਲ ਸੋ ਸੋਹ। ਦਿਜ ਚਰਜ ਤੁਲਿ ਮ੍ਰਿਗ ਚਰਮ ਅਰੋਹ। ੫੧।","roman":"Bibhram bibhoot ujal so soh | dij charaj tuli mrig charam aroh | 51 |","meaning_en":"The bright ash shone on him wondrously; like a Brahmin student he wore a deerskin.","page":820,"meaning_status":"draft","note":"ਬਿਭ੍ਰਮ: 'wondrous' or 'dispelling illusion'; uncertain. ਦਿਜ ਚਰਜ: brahmacharya."}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":820,"lines":[{"gurmukhi":"ਮੁਖ ਸਿਤ ਬਿਭੂਤ ਲੰਗੋਟ ਬੰਦ। ਸੰਨ੍ਯਾਸ ਚਰਜ ਤਜਿ ਛੰਦ ਬੰਦ।","roman":"Mukh sit bibhoot langot band | sannyaas charaj taji chhand band |","meaning_en":"White ash on his face, a loincloth tied, practising the sannyasi's discipline, abandoning tricks and snares,","page":820,"meaning_status":"draft","note":"ਛੰਦ ਬੰਦ: 'wiles and bonds'."},{"gurmukhi":"ਆਸੁਨਕ ਸੁਨਿ ਅਨਵ੍ਯਕਤ ਅੰਗ। ਆਛਿਜ ਤੇਜ ਮਹਿਮਾ ਸੁਰੰਗ। ੫੨।","roman":"Aasunak suni anvyakat ang | aachhij tej mahimaa surang | 52 |","meaning_en":"...of unmanifest limbs, indestructible splendour, and beautiful glory.","page":820,"meaning_status":"draft","note":"ਆਸੁਨਕ ਸੁਨਿ: obscure; perhaps 'like Sanak, the son of Brahma'; uncertain."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":820,"lines":[{"gurmukhi":"ਇਕ ਆਸ ਚਿਤ ਤਜਿ ਸਰਬ ਆਸ। ਅਨਭੂਤ ਗਾਤ ਨਿਸ ਦਿਨ ਉਦਾਸ।","roman":"Ik aas chit taji sarab aas | anbhoot gaat nis din udaas |","meaning_en":"Hope in the One in his mind, all other hopes abandoned; of wondrous body, detached night and day.","page":820,"meaning_status":"draft"},{"gurmukhi":"ਮੁਨਿ ਚਰਜ ਲੀਨ ਤਜਿ ਸਰਬ ਕਾਮ। ਆਰਕਤਿ ਨੇਤ੍ਰ ਜਨੁ ਧਰਮ ਧਾਮ। ੫੩।","roman":"Muni charaj leen taji sarab kaam | aarakti netr janu dharam dhaam | 53 |","meaning_en":"He took up the sage's discipline, giving up all desire; his reddish eyes as if the abode of dharma.","page":820,"meaning_status":"draft","note":"ਆਰਕਤਿ: 'reddish'; uncertain."}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":821,"lines":[{"gurmukhi":"ਅਬਿਕਾਰ ਚਿਤ ਅਣਡੋਲ ਅੰਗ। ਜੁਤ ਧਿਆਨ ਨੇਤ੍ਰ ਮਹਿਮਾ ਅਭੰਗ।","roman":"Abikaar chit andol ang | jut dhiaan netr mahimaa abhang |","meaning_en":"Mind without blemish, limbs unshaken, eyes absorbed in meditation, glory unbroken;","page":821,"meaning_status":"draft"},{"gurmukhi":"ਧਰਿ ਏਕ ਆਸ ਅਉਦਾਸ ਚਿਤ। ਸੰਨਿਯਾਸ ਦੇਵ ਪਰਮੰ ਪਵਿਤ। ੫੪।","roman":"Dhari ek aas audaas chit | sanniyaas dev parman pavit | 54 |","meaning_en":"holding one hope, mind detached — the god of sannyas, supremely pure.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":821,"lines":[{"gurmukhi":"ਅਵਧੂਤ ਗਾਤ ਮਹਿਮਾ ਅਪਾਰ। ਸ੍ਰੁਤਿ ਗਿਆਨ ਸਿੰਧੁ ਬਿਦਿਆ ਉਦਾਰ।","roman":"Avdhoot gaat mahimaa apaar | sruti giaan sindhu bidiaa udaar |","meaning_en":"Avadhut in body, boundless in glory, an ocean of the knowledge of the Vedas, generous in learning;","page":821,"meaning_status":"draft"},{"gurmukhi":"ਮੁਨਿ ਮਨਿ ਪ੍ਰਬੀਨ ਗੁਨਿ ਗਨ ਮਹਾਨ। ਜਨੁ ਭਯੋ ਪਰਮ ਗਿਆਨੀ ਮਹਾਨ। ੫੫।","roman":"Muni mani prabeen guni gan mahaan | janu bhayo param giaanee mahaan | 55 |","meaning_en":"jewel of sages, skilled, great in virtues — as though a supreme sage of knowledge had come into being.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":821,"lines":[{"gurmukhi":"ਕਬਹੂੰ ਨ ਪਾਪ ਜਿਹ ਛੁਹਾ ਅੰਗ। ਗੁਨਿ ਗਨ ਸੰਪੰਨ ਸੁੰਦਰ ਸੁਰੰਗ।","roman":"Kabhoon na paap jih chhuhaa ang | guni gan sanpann sundar surang |","meaning_en":"Sin never touched his body; rich in virtues, beautiful and fair;","page":821,"meaning_status":"draft"},{"gurmukhi":"ਲੰਗੋਟਬੰਦ ਅਵਧੂਤ ਗਾਤ। ਚਕਿ ਰਹੀ ਚਿਤ ਅਵਲੋਕਿ ਮਾਤ। ੫੬।","roman":"Langotband avdhoot gaat | chaki rahee chit avloki maat | 56 |","meaning_en":"wearing a loincloth, an Avadhut in body; seeing him, his mother was astonished in her heart.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":821,"lines":[{"gurmukhi":"ਸੰਨਿਯਾਸ ਦੇਵ ਅਨਭੂਤ ਅੰਗ। ਲਾਜੰਤ ਦੇਖਿ ਜਿਹ ਦੁਤਿ ਅਨੰਗ।","roman":"Sanniyaas dev anbhoot ang | laajant dekhi jih duti anang |","meaning_en":"The god of sannyas, of wondrous limbs, at whose radiance Anang (Kama) is ashamed;","page":821,"meaning_status":"draft"},{"gurmukhi":"ਮੁਨਿ ਦਤ ਦੇਵ ਸੰਨ੍ਯਾਸ ਰਾਜ। ਜਿਹ ਸਧੇ ਸਰਬ ਸੰਨ੍ਯਾਸ ਸਾਜ। ੫੭।","roman":"Muni dat dev sannyaas raaj | jih sadhe sarab sannyaas saaj | 57 |","meaning_en":"the sage Datt the divine, king of sannyasis, who perfected all the ways of renunciation.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":821,"lines":[{"gurmukhi":"ਪਰਮੰ ਪਵਿਤ੍ਰ ਜਾ ਕੇ ਸਰੀਰ। ਕਬਹੂੰ ਨ ਕਾਮ ਕਿਨੋ ਅਧੀਰ।","roman":"Parman pavitr jaa ke sareer | kabhoon na kaam kino adheer |","meaning_en":"Supremely pure was his body; lust never made him restless.","page":821,"meaning_status":"draft"},{"gurmukhi":"ਜਟ ਜੋਗ ਜਾਸੁ ਸੋਭੰਤ ਸੀਸ। ਅਸ ਧਰਾ ਰੂਪ ਸੰਨਿਯਾਸ ਈਸ। ੫੮।","roman":"Jat jog jaasu sobhant sees | as dharaa roop sanniyaas ees | 58 |","meaning_en":"The matted locks of yoga shone on his head; such was the form taken by the lord of sannyasis.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":821,"lines":[{"gurmukhi":"ਆਭਾ ਅਪਾਰ ਕਥਿ ਸਕੈ ਕਉਨ। ਸੁਨਿ ਰਹੈ ਜਛ ਗੰਧ੍ਰਬ ਮਉਨ।","roman":"Aabhaa apaar kathi sakai kaun | suni rahai jachh gandhrab maun |","meaning_en":"Who can tell his boundless radiance? Hearing of it, Yakshas and Gandharvas fell silent.","page":821,"meaning_status":"draft"},{"gurmukhi":"ਚਕਿ ਰਹਿਓ ਬ੍ਰਹਮ ਆਭਾ ਬਿਚਾਰਿ। ਲਾਜਯੋ ਅਨੰਗ ਆਭਾ ਨਿਹਾਰਿ। ੫੯।","roman":"Chaki rahio braham aabhaa bichaari | laajyo anang aabhaa nihaari | 59 |","meaning_en":"Brahma was astonished, considering his radiance; Anang was ashamed, beholding it.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":821,"lines":[{"gurmukhi":"ਅਤਿ ਗਿਆਨਵੰਤ ਕਰਮਨ ਪ੍ਰਬੀਨ। ਅਨ੍ਆਸ ਹਰਿ ਕੋ ਅਧੀਨ।","roman":"Ati giaanvant karman prabeen | ana'aas hari ko adheen |","meaning_en":"Highly knowing, skilled in deeds, free of hopes, devoted to Hari;","page":821,"meaning_status":"draft","note":"ਅਨ੍ਆਸ: printed so; read as 'an-aas' (without desire)."},{"gurmukhi":"ਛਬਿ ਦਿਪਤ ਕੋਟ ਸੂਰਜ ਪ੍ਰਮਾਨ। ਚਕ ਰਹਾ ਚੰਦ ਲਖਿ ਆਸਮਾਨ। ੬੦।","roman":"Chhabi dipat kot sooraj pramaan | chak rahaa chand lakhi aasmaan | 60 |","meaning_en":"his beauty blazed like ten million suns; the moon in the sky was astonished to see it.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":821,"lines":[{"gurmukhi":"ਉਪਜਿਯਾ ਆਪ ਇਕ ਜੋਗ ਰੂਪ। ਪੁਨਿ ਲਗੋ ਜੋਗ ਸਾਧਨ ਅਨੂਪ।","roman":"Upjiyaa aap ik jog roop | puni lago jog saadhan anoop |","meaning_en":"He was born himself a form of yoga, and then took up incomparable practice of yoga.","page":821,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਰਿਹ ਪ੍ਰਿਥਮ ਛਾਡਿ ਉਠਿ ਚਲਾ ਦਤ। ਪਰਮੰ ਪਵਿਤ੍ਰ ਨਿਰਮਲੀ ਮਤਿ। ੬੧।","roman":"Grih pritham chhaadi uthi chalaa dat | parman pavitr niramlee mati | 61 |","meaning_en":"First Datt left his home and set out, supremely pure, of spotless mind.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":821,"lines":[{"gurmukhi":"ਜਬ ਕੀਨ ਜੋਗ ਬਹੁ ਦਿਨ ਪ੍ਰਮਾਨ। ਤਬ ਕਾਲ ਦੇਵ ਰੀਝੇ ਨਿਦਾਨ।","roman":"Jab keen jog bahu din pramaan | tab kaal dev reejhe nidaan |","meaning_en":"When he had done yoga for many days, then at last the Lord Kal was pleased;","page":821,"meaning_status":"draft"},{"gurmukhi":"ਇਮਿ ਭਈ ਬਿਓਮਬਾਨੀ ਬਨਾਇ। ਤੁਮ ਸੁਣਹੁ ਬੈਨ ਸੰਨ੍ਯਾਸ ਰਾਇ। ੬੨।","roman":"Imi bhaee biombaanee banaai | tum sunhu bain sannyaas raai | 62 |","meaning_en":"thus a voice from the sky spoke: \"Listen to these words, king of sannyasis.\"","page":821,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਆਕਾਸ ਬਾਨੀ ਬਾਚਿ ਦਤ ਪ੍ਰਤਿ","gurmukhi":"ਆਕਾਸ ਬਾਨੀ ਬਾਚਿ ਦਤ ਪ੍ਰਤਿ","roman":"Aakaas baanee baachi dat prati","meaning_en":"The voice from the sky said to Datt:","page":821,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਪਾਧੜੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"Padhari metre.","page":821,"meaning_status":"draft"},{"type":"verse","number":[63],"number_text":"੬੩।","page":821,"lines":[{"gurmukhi":"ਗੁਰ ਹੀਣ ਮੁਕਤਿ ਨਹੀ ਹੋਤ ਦਤ। ਤੁਹਿ ਕਹੋ ਬਾਤ ਸੁਨਿ ਬਿਮਲ ਮਤ।","roman":"Gur heen mukti nahee hot dat | tuhi kaho baat suni bimal mat |","meaning_en":"\"Without a guru there is no liberation, Datt; I tell you this — listen, you of pure mind.","page":821,"meaning_status":"draft"},{"gurmukhi":"ਗੁਰ ਕਰਹਿ ਪ੍ਰਿਥਮ ਤਬ ਹੋਗਿ ਮੁਕਤਿ। ਕਹਿ ਦੀਨ ਕਾਲ ਤਿਹ ਜੋਗ ਜੁਗਤ। ੬੩।","roman":"Gur karhi pritham tab hogi mukti | kahi deen kaal tih jog jugat | 63 |","meaning_en":"First take a guru, then there will be liberation.\" Thus Kal told him the method of yoga.","page":821,"meaning_status":"draft"}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":822,"lines":[{"gurmukhi":"ਬਹੁ ਭਾਤਿ ਦਤ ਦੰਡਵਤ ਕੀਨ। ਆਸਾ ਬਿਰਹਤਿ ਹਰਿ ਕੋ ਅਧੀਨ।","roman":"Bahu bhaati dat dandvat keen | aasaa birahti hari ko adheen |","meaning_en":"Datt prostrated himself in many ways, free of desire, devoted to Hari;","page":822,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਭਾਤ ਜੋਗ ਸਾਧਨਾ ਸਾਧਿ। ਆਦਗ ਜੋਗ ਮਹਿਮਾ ਅਗਾਧ। ੬੪।","roman":"Bahu bhaat jog saadhnaa saadhi | aadag jog mahimaa agaadh | 64 |","meaning_en":"he performed the practices of yoga in many ways — the primal yoga, of unfathomable glory.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":822,"lines":[{"gurmukhi":"ਤਬ ਨਮਸਕਾਰ ਕਰਿ ਦਤ ਦੇਵ। ਉਚਰੰਤ ਪਰਮ ਉਸਤਤਿ ਅਭੇਵ।","roman":"Tab namaskaar kari dat dev | uchrant param usatti abhev |","meaning_en":"Then Datt the divine, bowing, uttered supreme praise of the Mysterious One:","page":822,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗੀਨ ਜੋਗ ਰਾਜਾਨ ਰਾਜ। ਅਨਭੂਤ ਅੰਗ ਜਹ ਤਹ ਬਿਰਾਜ। ੬੫।","roman":"Jogeen jog raajaan raaj | anbhoot ang jah tah biraaj | 65 |","meaning_en":"\"Yogi of yogis, king of kings, of wondrous form, present here and there,","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":822,"lines":[{"gurmukhi":"ਜਲ ਥਲ ਬਿਯਾਪ ਜਿਹ ਤੇਜ ਏਕ। ਗਾਵੰਤ ਜਾਸੁ ਮੁਨਿ ਗਨ ਅਨੇਕ।","roman":"Jal thal biyaap jih tej ek | gaavant jaasu muni gan anek |","meaning_en":"whose one light pervades water and land, whom many hosts of sages sing,","page":822,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਨੇਤਿ ਨੇਤਿ ਭਾਖੰਤ ਨਿਗਮ। ਤੇ ਆਦਿ ਅੰਤ ਮਧਹ ਅਗਮ। ੬੬।","roman":"Jih neti neti bhaakhant nigam | te aadi ant madhah agam | 66 |","meaning_en":"whom the Vedas call 'not this, not this' — He is unreachable in beginning, end and middle.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":822,"lines":[{"gurmukhi":"ਜਿਹ ਏਕ ਰੂਪ ਕਿਨੇ ਅਨੇਕ। ਪੁਹਮੀ ਅਕਾਸ ਕਿਨੇ ਬਿਬੇਕ।","roman":"Jih ek roop kine anek | puhmee akaas kine bibek |","meaning_en":"He who made the one form into many, and separated earth and sky;","page":822,"meaning_status":"draft"},{"gurmukhi":"ਜਲ ਬਾ ਥਲੇਸ ਸਬ ਠੌਰ ਜਾਨ। ਅਨਭੈ ਅਜੋਨਿ ਅਨਿ ਆਸ ਮਾਨ। ੬੭।","roman":"Jal baa thales sab thaur jaan | anbhai ajoni ani aas maan | 67 |","meaning_en":"know Him as lord of water and land, in every place — fearless, unborn, without desire.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":822,"lines":[{"gurmukhi":"ਪਾਵਨ ਪ੍ਰਸਿਧ ਪਰਮੰ ਪੁਨੀਤ। ਆਜਾਨ ਬਾਹ ਅਨਭਉ ਅਜੀਤ।","roman":"Paavan prasidh parman puneet | aajaan baah anbhau ajeet |","meaning_en":"Holy, renowned, supremely pure, arms reaching to the knees, fearless, unconquered;","page":822,"meaning_status":"draft"},{"gurmukhi":"ਪਰਮੰ ਪ੍ਰਸਿਧ ਪੂਰਣ ਪੁਰਾਣ। ਰਾਜਾਨ ਰਾਜ ਭੋਗੀ ਮਹਾਣ। ੬੮।","roman":"Parman prasidh pooran puraan | raajaan raaj bhogee mahaan | 68 |","meaning_en":"supremely renowned, perfect, ancient, king of kings, the great enjoyer.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":822,"lines":[{"gurmukhi":"ਅਨਛਿਜ ਤੇਜ ਅਨਭੈ ਪ੍ਰਕਾਸ। ਖੜਗਨ ਸਪੰਨ ਪਰਮੰ ਪ੍ਰਭਾਸ।","roman":"Anchhij tej anbhai prakaas | khargan sapann parman prabhaas |","meaning_en":"Indestructible splendour, fearless light, endowed with the sword, of supreme brilliance;","page":822,"meaning_status":"draft","note":"ਖੜਗਨ ਸਪੰਨ: 'possessed of the sword'."},{"gurmukhi":"ਆਭਾ ਅਨੰਤ ਬਰਨੀ ਨ ਜਾਇ। ਫਿਰ ਫਿਰੋ ਸਰਬ ਮਤਿ ਕੋ ਚਲਾਇ। ੬੯।","roman":"Aabhaa anant barnee na jaai | phir phiro sarab mati ko chalaai | 69 |","meaning_en":"His endless radiance cannot be described; He set going all the creeds again and again.","page":822,"meaning_status":"draft","note":"ਫਿਰ ਫਿਰੋ: sense uncertain."}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":822,"lines":[{"gurmukhi":"ਸਬਹੂ ਬਖਾਨ ਜਿਹ ਨੇਤਿ ਨੇਤਿ। ਅਕਲੰਕ ਰੂਪ ਆਭਾ ਅਮੇਤ।","roman":"Sabhoo bakhaan jih neti neti | aklank roop aabhaa amet |","meaning_en":"Whom all describe as 'not this, not this', of stainless form and measureless radiance;","page":822,"meaning_status":"draft"},{"gurmukhi":"ਸਰਬੰ ਸਮ੍ਰਿਧ ਜਿਹ ਪਾਨ ਲਾਗ। ਜਿਹ ਨਾਮ ਲੇਤ ਸਬ ਪਾਪ ਭਾਗ। ੭੦।","roman":"Sarban samridh jih paan laag | jih naam let sab paap bhaag | 70 |","meaning_en":"at whose feet all riches fall, by taking whose Name all sins flee.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":822,"lines":[{"gurmukhi":"ਗੁਨ ਸੀਲ ਸਾਧੁ ਤਾ ਕੇ ਸੁਭਾਇ। ਬਿਨੁ ਤਾਸ ਸਰਨਿ ਨਹੀ ਕੋਊ ਉਪਾਇ।","roman":"Gun seel saadhu taa ke subhaai | binu taas sarni nahee ko'oo upaai |","meaning_en":"Virtue, gentleness and goodness are His nature; without His refuge there is no other way.","page":822,"meaning_status":"draft"},{"gurmukhi":"ਦੀਨਨ ਉਧਾਰਣਿ ਜਾਸੁ ਬਾਨ। ਕੋਊ ਕਹੈ ਕੈਸੇਈ ਲੇਤ ਮਾਨ। ੭੧।","roman":"Deenan udhaarni jaasu baan | ko'oo kahai kaise'ee let maan | 71 |","meaning_en":"Whose habit is to uplift the lowly; whatever anyone says, He accepts it.","page":822,"meaning_status":"draft","note":"Second half uncertain: 'however one calls on Him, He accepts'."}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":822,"lines":[{"gurmukhi":"ਅਕਲੰਕ ਰੂਪ ਅਨਛਿਜ ਤੇਜ। ਆਸਨ ਅਡੋਲ ਸੁਭ ਸੁਭ੍ਰ ਸੇਜ।","roman":"Aklank roop anchhij tej | aasan adol subh subhr sej |","meaning_en":"Stainless form, indestructible splendour, unshaken seat, fair and bright couch;","page":822,"meaning_status":"draft"},{"gurmukhi":"ਅਨਗਨ ਜਾਸੁ ਗੁਨ ਮਧਿ ਸੋਭ। ਲਖਿ ਸਤ੍ਰ ਮਿਤ੍ਰ ਜਿਹ ਰਹਤ ਲੋਭ। ੭੨।","roman":"Angan jaasu gun madhi sobh | lakhi satr mitr jih rahat lobh | 72 |","meaning_en":"countless virtues shine in Him; seeing Him, friend and foe alike are enchanted.","page":822,"meaning_status":"draft","note":"ਲੋਭ: here 'drawn, enchanted'."}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":822,"lines":[{"gurmukhi":"ਜਿਹ ਸਤ੍ਰ ਮਿਤ੍ਰ ਸਮ ਏਕ ਜਾਨ। ਉਸਤਤੀ ਨਿੰਦ ਜਿਹ ਏਕ ਮਾਨ।","roman":"Jih satr mitr sam ek jaan | usattee nind jih ek maan |","meaning_en":"Who knows friend and foe as one, who regards praise and blame as one;","page":822,"meaning_status":"draft"},{"gurmukhi":"ਆਸਨ ਅਡੋਲ ਅਨਛਿਜ ਰੂਪ। ਪਰਮੰ ਪਵਿਤ੍ਰ ਭੂਪਾਣ ਭੂਪ। ੭੩।","roman":"Aasan adol anchhij roop | parman pavitr bhoopaan bhoop | 73 |","meaning_en":"unshaken seat, indestructible form, supremely pure, king of kings.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":822,"lines":[{"gurmukhi":"ਜਿਹਬਾ ਸੁਧਾਨ ਖਗ ਉਧ ਸੋਹਿ। ਅਵਿਲੋਕ ਦਈਤ ਅਰੁ ਦੇਵ ਮੋਹਿ।","roman":"Jihbaa sudhaan khag udh sohi | avilok daeet aru dev mohi |","meaning_en":"Whose tongue is like nectar, His sword raised and shining; seeing Him, demons and gods are enchanted;","page":822,"meaning_status":"draft","note":"ਖਗ ਉਧ: 'raised sword'; uncertain."},{"gurmukhi":"ਬਿਨੁ ਬੈਰ ਰੂਪ ਅਨਭਵ ਪ੍ਰਕਾਸ। ਅਨਛਿਜ ਗਾਤ ਨਿਸਿ ਦਿਨ ਨਿਰਾਸ। ੭੪।","roman":"Binu bair roop anbhav prakaas | anchhij gaat nisi din niraas | 74 |","meaning_en":"without enmity in form, light of experience, of indestructible body, desireless night and day.","page":822,"meaning_status":"draft"}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":823,"lines":[{"gurmukhi":"ਦੁਤਿ ਆਦਿ ਅੰਤਿ ਏਕੈ ਸਮਾਨ। ਖੜਗੰਨ ਸਪੰਨਿ ਸਬ ਬਿਧਿ ਨਿਧਾਨ।","roman":"Duti aadi anti ekai samaan | khargann sapanni sab bidhi nidhaan |","meaning_en":"His radiance in beginning and end is one and the same; endowed with the sword, treasury of every means.","page":823,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਾ ਸੁ ਬਹੁਤ ਤਨ ਜਾਸੁ ਸੋਭ। ਦੁਤਿ ਦੇਖਿ ਜਛ ਗੰਧ੍ਰਬ ਲੋਭ। ੭੫।","roman":"Sobhaa su bahut tan jaasu sobh | duti dekhi jachh gandhrab lobh | 75 |","meaning_en":"Great beauty shines on His body; seeing His radiance, Yakshas and Gandharvas are enchanted.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":823,"lines":[{"gurmukhi":"ਅਨਭੰਗ ਅੰਗ ਅਨਭਵ ਪ੍ਰਕਾਸ। ਪਸਰੀ ਜਗਤਿ ਜਿਹ ਜੀਵ ਰਾਸਿ।","roman":"Anbhang ang anbhav prakaas | pasree jagti jih jeev raasi |","meaning_en":"Unbroken in limb, light of experience, through whom the mass of living beings spread in the world;","page":823,"meaning_status":"draft"},{"gurmukhi":"ਕਿਨੇ ਸੁ ਜੀਵ ਜਲਿ ਥਲਿ ਅਨੇਕ। ਅੰਤਹਿ ਸਮੇਯ ਫੁਨਿ ਰੂਪ ਏਕ। ੭੬।","roman":"Kine su jeev jali thali anek | anthi samey phuni roop ek | 76 |","meaning_en":"who made many beings in water and on land, and at the end time they become one form again.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":823,"lines":[{"gurmukhi":"ਜਿਹ ਛੂਆ ਨੈਕੁ ਨਹੀ ਕਾਲ ਜਾਲੁ। ਛ੍ਵੈ ਸਕਾ ਪਾਪ ਨਹੀ ਕਉਨ ਕਾਲ।","roman":"Jih chhooaa naiku nahee kaal jaalu | chhvai sakaa paap nahee kaun kaal |","meaning_en":"Whom the net of death has not touched at all, whom sin could never touch at any time;","page":823,"meaning_status":"draft"},{"gurmukhi":"ਆਛਿਜ ਤੇਜ ਅਨਭੂਤ ਗਾਤ। ਏਕੈ ਸਰੂਪ ਨਿਸ ਦਿਨ ਪ੍ਰਭਾਤ। ੭੭।","roman":"Aachhij tej anbhoot gaat | ekai saroop nis din prabhaat | 77 |","meaning_en":"indestructible splendour, wondrous body, of one form night, day and dawn.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":823,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਦਤ ਅਸਤੋਤ੍ਰ ਪਾਠ। ਮੁਖ ਪੜਤ ਅਛ੍ਰ ਗਯੋ ਪਾਪ ਨਾਠ।","roman":"Ih bhaati dat astotr paath | mukh parat achhr gayo paap naath |","meaning_en":"In this way Datt recited the hymn of praise; as he read the syllables with his mouth, sin fled.","page":823,"meaning_status":"draft"},{"gurmukhi":"ਕੋ ਸਕੈ ਬਰਨ ਮਹਿਮਾ ਅਪਾਰ। ਸੰਛੇਪ ਕੀਨ ਤਾ ਤੇ ਉਚਾਰ। ੭੮।","roman":"Ko sakai baran mahimaa apaar | sanchhep keen taa te uchaar | 78 |","meaning_en":"Who can describe the boundless glory? Therefore I have told it in brief.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":823,"lines":[{"gurmukhi":"ਜੇ ਕਰੈ ਪਤ੍ਰ ਕਾਸਿਪੀ ਸਰਬ। ਲਿਖੇ ਗਣੇਸ ਕਰਿ ਕੈ ਸੁ ਗਰਬ।","roman":"Je karai patr kaasipee sarab | likhe ganes kari kai su garab |","meaning_en":"If the whole earth were made into paper, and Ganesh wrote, taking pride in it,","page":823,"meaning_status":"draft","note":"ਕਾਸਿਪੀ: the earth (daughter of Kashyap)."},{"gurmukhi":"ਮਸੁ ਸਰਬ ਸਿੰਧ ਲੇਖਕ ਬਨੇਸਿ। ਨਹੀ ਤਦਿਪ ਅੰਤਿ ਕਹਿ ਸਕੈ ਸੇਸੁ। ੭੯।","roman":"Masu sarab sindh lekhak banesi | nahee tadip anti kahi sakai sesu | 79 |","meaning_en":"with all the oceans as ink and the forests as pens, still Shesh could not tell His end.","page":823,"meaning_status":"draft","note":"ਬਨੇਸਿ: read as forests (as pens); uncertain."}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":823,"lines":[{"gurmukhi":"ਜਉ ਕਰੈ ਬੈਠਿ ਬ੍ਰਹਮਾ ਉਚਾਰ। ਨਹੀ ਤਦਿਪ ਤੇਜ ਪਾਯੰਤ ਪਾਰ।","roman":"Jau karai baithi brahmaa uchaar | nahee tadip tej paayant paar |","meaning_en":"If Brahma sat and uttered (His praise), even then he could not reach the limit of His splendour;","page":823,"meaning_status":"draft"},{"gurmukhi":"ਮੁਖ ਸਹੰਸ ਨਾਮ ਫਣ ਪਤਿ ਰੜੰਤ। ਨਹੀ ਤਦਿਪ ਤਾਸੁ ਪਾਯੰਤ ਅੰਤੁ। ੮੦।","roman":"Mukh sahans naam phan pati rarant | nahee tadip taasu paayant antu | 80 |","meaning_en":"the lord of the serpent-hoods recites the thousand names with his mouths, yet does not find His end.","page":823,"meaning_status":"draft","note":"ਫਣ ਪਤਿ: Sheshnag."}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":823,"lines":[{"gurmukhi":"ਨਿਸ ਦਿਨ ਜਪੰਤ ਸਨਕੰ ਸਨਾਤ। ਨਹੀ ਤਦਿਪ ਤਾਸੁ ਸੋਭਾ ਨਿਰਾਤ।","roman":"Nis din japant sankan sanaat | nahee tadip taasu sobhaa niraat |","meaning_en":"Sanak and Sanatan repeat it night and day, yet His beauty is not fully told.","page":823,"meaning_status":"draft","note":"ਨਿਰਾਤ: sense uncertain ('exhausted'?)."},{"gurmukhi":"ਮੁਖ ਚਾਰ ਬੇਦ ਕਿਨੇ ਉਚਾਰ। ਤਜਿ ਗਰਬ ਨੇਤਿ ਨੇਤੈ ਬਿਚਾਰ। ੮੧।","roman":"Mukh chaar bed kine uchaar | taji garab neti netai bichaar | 81 |","meaning_en":"The four Vedas spoke from (Brahma's) mouths, and, giving up pride, concluded 'not this, not this'.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":823,"lines":[{"gurmukhi":"ਸਿਵ ਸਹੰਸ੍ਰ ਬਰਖ ਲੌ ਜੋਗ ਕੀਨ। ਤਜਿ ਨੇਹ ਗੇਹ ਬਨ ਬਾਸ ਲੀਨ।","roman":"Siv sahansr barakh lau jog keen | taji neh geh ban baas leen |","meaning_en":"Shiva practised yoga for a thousand years, gave up love and home, and lived in the forest;","page":823,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਕੀਨ ਜੋਗ ਤਹ ਬਹੁ ਪ੍ਰਕਾਰ। ਨਹੀ ਤਦਿਪ ਤਾਸੁ ਲਹਿ ਸਕਾ ਪਾਰ। ੮੨।","roman":"Bahu keen jog tah bahu prakaar | nahee tadip taasu lahi sakaa paar | 82 |","meaning_en":"he did yoga there in many ways, yet could not find His limit.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":823,"lines":[{"gurmukhi":"ਜਿਹ ਏਕ ਰੂਪ ਅਨਕੰ ਪ੍ਰਕਾਸ। ਅਬਿਯਕਤ ਤੇਜ ਨਿਸ ਦਿਨ ਉਦਾਸ।","roman":"Jih ek roop ankan prakaas | abiykat tej nis din udaas |","meaning_en":"Whose one form shines as many, of unmanifest splendour, detached night and day;","page":823,"meaning_status":"draft"},{"gurmukhi":"ਆਸਨ ਅਡੋਲ ਮਹਿਮਾ ਅਭੰਗ। ਅਨਭਵ ਪ੍ਰਕਾਸ ਸੋਭਾ ਸੁਰੰਗ। ੮੩।","roman":"Aasan adol mahimaa abhang | anbhav prakaas sobhaa surang | 83 |","meaning_en":"unshaken seat, unbroken glory, light of experience, beautiful and fair.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":823,"lines":[{"gurmukhi":"ਜਿਹ ਸਤ੍ਰੁ ਮਿਤ੍ਰ ਏਕੈ ਸਮਾਨ। ਅਬਿਯਕਤ ਤੇਜ ਮਹਿਮਾ ਮਹਾਨ।","roman":"Jih satru mitr ekai samaan | abiykat tej mahimaa mahaan |","meaning_en":"To whom friend and foe are alike, of unmanifest splendour and great glory;","page":823,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਆਦਿ ਅੰਤਿ ਏਕੈ ਸਰੂਪ। ਸੁੰਦਰ ਸੁਰੰਗ ਜਗ ਕਰਿ ਅਰੂਪ। ੮੪।","roman":"Jih aadi anti ekai saroop | sundar surang jag kari aroop | 84 |","meaning_en":"who in beginning and end is of one form, beautiful and fair; making the world, Himself formless.","page":823,"meaning_status":"draft"}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":824,"lines":[{"gurmukhi":"ਜਿਹ ਰਾਗ ਰੰਗ ਨਹੀ ਰੂਪ ਰੇਖ। ਨਹੀ ਨਾਮ ਠਾਮ ਅਨਭਵ ਅਭੇਖ।","roman":"Jih raag rang nahee roop rekh | nahee naam thaam anbhav abhekh |","meaning_en":"Who has no attachment, colour, form or feature, no name or place, light of experience, without garb;","page":824,"meaning_status":"draft"},{"gurmukhi":"ਆਜਾਨ ਬਾਹਿ ਅਨਭਵ ਪ੍ਰਕਾਸ। ਆਭਾ ਅਨੰਤ ਮਹਿਮਾ ਸੁ ਬਾਸ। ੮੫।","roman":"Aajaan baahi anbhav prakaas | aabhaa anant mahimaa su baas | 85 |","meaning_en":"arms reaching to the knees, light of experience, endless radiance, glory and fragrance.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":824,"lines":[{"gurmukhi":"ਕਈ ਕਲਪ ਜੋਗ ਜਿਨਿ ਕਰਤ ਬੀਤ। ਨਹੀ ਤਦਿਪ ਤਉਨ ਧਰਿ ਗਏ ਚੀਤ।","roman":"Kaee kalap jog jini karat beet | nahee tadip taun dhari gae cheet |","meaning_en":"Those in whom many ages passed doing yoga — even so He did not come into their minds;","page":824,"meaning_status":"draft"},{"gurmukhi":"ਮੁਨਿ ਮਨ ਅਨੇਕ ਗੁਨਿ ਗਨ ਮਹਾਨ। ਬਹੁ ਕਸਟ ਕਰਤ ਨਹੀ ਧਰਤ ਧਿਆਨ। ੮੬।","roman":"Muni man anek guni gan mahaan | bahu kasat karat nahee dharat dhiaan | 86 |","meaning_en":"many jewels of sages, great in virtues, enduring much hardship, could not fix Him in meditation.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":824,"lines":[{"gurmukhi":"ਜਿਹ ਏਕ ਰੂਪ ਕਿਨੇ ਅਨੇਕ। ਅੰਤਹਿ ਸਮੇਯ ਫੁਨਿ ਭਏ ਏਕ।","roman":"Jih ek roop kine anek | anthi samey phuni bhae ek |","meaning_en":"Who made the one form into many, and at the end time they became one again;","page":824,"meaning_status":"draft"},{"gurmukhi":"ਕਈ ਕੋਟਿ ਜੰਤ ਜੀਵਨ ਉਪਾਇ। ਫਿਰਿ ਅੰਤ ਲੇਤ ਆਪਹਿ ਮਿਲਾਇ। ੮੭।","roman":"Kaee koti jant jeevan upaai | phiri ant let aaphi milaai | 87 |","meaning_en":"creating many millions of creatures and beings, then at the end He merges them into Himself.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":824,"lines":[{"gurmukhi":"ਜਿਹ ਜਗਤ ਜੀਵ ਸਬ ਪਰੇ ਸਰਨਿ। ਮੁਨ ਮਨਿ ਅਨੇਕ ਜਿਹ ਜਪਤ ਚਰਨ।","roman":"Jih jagat jeev sab pare sarni | mun mani anek jih japat charan |","meaning_en":"In whose refuge all the beings of the world lie, whose feet many jewels of sages meditate on;","page":824,"meaning_status":"draft"},{"gurmukhi":"ਕਈ ਕਲਪ ਤਿਹੰ ਕਰਤ ਧਿਆਨ। ਕਹੂੰ ਨ ਦੇਖਿ ਤਿਹ ਬਿਦਿਮਾਨ। ੮੮।","roman":"Kaee kalap tihan karat dhiaan | kahoon na dekhi tih bidimaan | 88 |","meaning_en":"for many ages they meditate on Him, yet nowhere have they seen Him present.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":824,"lines":[{"gurmukhi":"ਆਭਾ ਅਨੰਤ ਮਹਿਮਾ ਅਪਾਰ। ਮੁਨ ਮਨਿ ਮਹਾਨ ਅਤ ਹੀ ਉਦਾਰ।","roman":"Aabhaa anant mahimaa apaar | mun mani mahaan at hee udaar |","meaning_en":"Endless radiance, boundless glory — great jewels among sages, very generous ones —","page":824,"meaning_status":"draft"},{"gurmukhi":"ਆਛਿਜ ਤੇਜ ਸੂਰਤਿ ਅਪਾਰ। ਨਹੀ ਸਕਤ ਬੁਧ ਕਰਿ ਕੈ ਬਿਚਾਰ। ੮੯।","roman":"Aachhij tej soorti apaar | nahee sakat budh kari kai bichaar | 89 |","meaning_en":"His indestructible splendour, His boundless form, they cannot reflect on with their intellect.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":824,"lines":[{"gurmukhi":"ਜਿਹ ਆਦਿ ਅੰਤਿ ਏਕਹਿ ਸਰੂਪ। ਸੋਭਾ ਅਭੰਗ ਮਹਿਮਾ ਅਨੂਪ।","roman":"Jih aadi anti ekhi saroop | sobhaa abhang mahimaa anoop |","meaning_en":"Who in beginning and end is of one form, of unbroken beauty and incomparable glory;","page":824,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਕੀਨ ਜੋਤਿ ਉਦੋਤ ਸਰਬ। ਜਿਹ ਹਤ੍ਯੋ ਸਰਬ ਗਰਬੀਨ ਗਰਬ। ੯੦।","roman":"Jih keen joti udot sarab | jih hatyo sarab garbeen garab | 90 |","meaning_en":"who made His light shine in all, who destroyed the pride of all the proud.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":824,"lines":[{"gurmukhi":"ਜਿਹ ਗਰਬਵੰਤ ਏਕੈ ਨ ਰਾਖ। ਫਿਰਿ ਕਹੋ ਬੈਣ ਨਹੀ ਬੈਣ ਭਾਖ।","roman":"Jih garabvant ekai na raakh | phiri kaho bain nahee bain bhaakh |","meaning_en":"Who left not one proud person standing; who, once He has spoken a word, does not speak it again;","page":824,"meaning_status":"draft","note":"Sense uncertain: 'His word once spoken does not change'."},{"gurmukhi":"ਇਕ ਬਾਰ ਮਾਰਿ ਮਾਰ੍ਯੋ ਨ ਸਤ੍ਰੁ। ਇਕ ਬਾਰ ਡਾਰਿ ਡਾਰਿਓ ਨ ਅਤ੍ਰ। ੯੧।","roman":"Ik baar maari maaryo na satru | ik baar daari daario na atr | 91 |","meaning_en":"who, having struck an enemy once, does not strike him again; having thrown a weapon once, does not throw it again.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":824,"lines":[{"gurmukhi":"ਸੇਵਕ ਥਾਪਿ ਨਹੀ ਦੂਰ ਕੀਨ। ਲਖਿ ਭਈ ਭੂਲ ਮੁਖਿ ਬਿਹਸ ਦੀਨ।","roman":"Sevak thaapi nahee door keen | lakhi bhaee bhool mukhi bihas deen |","meaning_en":"Having established a servant, He has not cast him away; seeing a mistake, He has only smiled.","page":824,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਗਹੀ ਬਾਹਿੰ ਕਿਨੋ ਨਿਬਾਹ। ਤ੍ਰੀਯਾ ਏਕ ਬ੍ਯਾਹਿ ਨਹੀ ਕੀਨ ਬ੍ਯਾਹ। ੯੨।","roman":"Jih gahee baahin kino nibaah | treeyaa ek byaahi nahee keen byaah | 92 |","meaning_en":"Whose arm He has grasped, He has stood by to the end; having wed one bride, He has not wed again.","page":824,"meaning_status":"draft","note":"Figurative of constancy; uncertain."}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":824,"lines":[{"gurmukhi":"ਰੀਝੰਤ ਕੋਟਿ ਨਹੀ ਕਸਟ ਕੀਨ। ਸੀਝੰਤ ਏਕ ਹੀ ਨਾਮ ਲੀਨ।","roman":"Reejhant koti nahee kasat keen | seejhant ek hee naam leen |","meaning_en":"He is not pleased by ten million austerities; He is won by taking the one Name alone.","page":824,"meaning_status":"draft"},{"gurmukhi":"ਅਨ ਕਪਟ ਰੂਪ ਅਨਭਉ ਪ੍ਰਕਾਸ। ਖੜਗਨ ਸਪੰਨਿ ਨਿਸ ਦਿਨ ਨਿਰਾਸ। ੯੩।","roman":"An kapat roop anbhau prakaas | khargan sapanni nis din niraas | 93 |","meaning_en":"Of guileless form, light of experience, endowed with the sword, desireless night and day.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":824,"lines":[{"gurmukhi":"ਪਰਮੰ ਪਵਿਤ੍ਰ ਪੂਰਣ ਪੁਰਾਣ। ਮਹਿਮਾ ਅਭੰਗ ਸੋਭਾ ਨਿਧਾਨ।","roman":"Parman pavitr pooran puraan | mahimaa abhang sobhaa nidhaan |","meaning_en":"Supremely pure, perfect, ancient, of unbroken glory, treasury of beauty;","page":824,"meaning_status":"draft"},{"gurmukhi":"ਪਾਵਨ ਪ੍ਰਸਿਧ ਪਰਮੰ ਪੁਨੀਤ। ਆਜਾਨ ਬਾਹੁ ਅਨਭੈ ਅਜੀਤ। ੯੪।","roman":"Paavan prasidh parman puneet | aajaan baahu anbhai ajeet | 94 |","meaning_en":"holy, renowned, supremely pure, arms reaching to the knees, fearless, unconquered.","page":824,"meaning_status":"draft"}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":825,"lines":[{"gurmukhi":"ਕਈ ਕੋਟਿ ਇੰਦ੍ਰ ਜਿਹ ਪਾਨਿਹਾਰ। ਕਈ ਚੰਦ ਸੂਰ ਕ੍ਰਿਸਨਾਵਤਾਰ।","roman":"Kaee koti indr jih paanihaar | kaee chand soor krisnaavtaar |","meaning_en":"Many millions of Indras are His water-carriers; many moons and suns and Krishna incarnations;","page":825,"meaning_status":"draft"},{"gurmukhi":"ਕਈ ਬਿਸਨ ਰੁਦ੍ਰ ਰਾਮਾ ਰਸੂਲ। ਬਿਨੁ ਭਗਤਿ ਯੌ ਨ ਕੋਈ ਕਬੂਲ। ੯੫।","roman":"Kaee bisan rudr raamaa rasool | binu bhagti yau na koee kabool | 95 |","meaning_en":"many Vishnus, Rudras, Rams and prophets — without devotion, none is accepted.","page":825,"meaning_status":"draft","note":"ਰਸੂਲ: Arabic, 'prophet/messenger'."}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":825,"lines":[{"gurmukhi":"ਕਈ ਦਤ ਸਤ ਗੋਰਖ ਦੇਵ। ਮੁਨਮਨਿ ਮਛਿੰਦ੍ਰ ਨਹੀ ਲਖਤ ਭੇਵ।","roman":"Kaee dat sat gorakh dev | munamni machhindr nahee lakhat bhev |","meaning_en":"Many Datts, Satts and Gorakhs, gods, jewels of sages, Machhindars do not know His mystery;","page":825,"meaning_status":"draft","note":"ਸਤ: perhaps a name or 'true ones'; uncertain."},{"gurmukhi":"ਬਹੁ ਭਾਤਿ ਮੰਤ੍ਰ ਮਤ ਕੈ ਪ੍ਰਕਾਸ। ਬਿਨੁ ਏਕ ਆਸ ਸਭ ਹੀ ਨਿਰਾਸ। ੯੬।","roman":"Bahu bhaati mantr mat kai prakaas | binu ek aas sabh hee niraas | 96 |","meaning_en":"many kinds of mantras and creeds have been made manifest; without hope in the One, all are hopeless.","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":825,"lines":[{"gurmukhi":"ਜਿਹ ਨੇਤਿ ਨੇਤਿ ਭਾਖਤ ਨਿਗਮ। ਕਰਤਾਰ ਸਰਬ ਕਾਰਣ ਅਗਮ।","roman":"Jih neti neti bhaakhat nigam | kartaar sarab kaaran agam |","meaning_en":"Whom the Vedas call 'not this, not this', the Creator, Cause of all, unreachable;","page":825,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਲਖਤ ਕੋਈ ਨਹੀ ਕਉਨ ਜਾਤਿ। ਜਿਹ ਨਾਹਿ ਪਿਤਾ ਭ੍ਰਿਤ ਤਾਤ ਮਾਤ। ੯੭।","roman":"Jih lakhat koee nahee kaun jaati | jih naahi pitaa bhrit taat maat | 97 |","meaning_en":"whose caste no one can tell, who has no father, brother, or mother.","page":825,"meaning_status":"draft","note":"ਭ੍ਰਿਤ: read as 'brother'; ਤਾਤ: father."}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":825,"lines":[{"gurmukhi":"ਜਾਨੀ ਨ ਜਾਤ ਜਿਹ ਰੰਗ ਰੂਪ। ਸਾਹਾਨ ਸਾਹਿ ਭੂਪਾਨ ਭੂਪ।","roman":"Jaanee na jaat jih rang roop | saahaan saahi bhoopaan bhoop |","meaning_en":"Whose colour and form cannot be known, King of kings, Lord of lords;","page":825,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਬਰਣ ਜਾਤਿ ਨਹੀ ਕ੍ਰਿਤ ਅਨੰਤ। ਆਦੋ ਅਪਾਰ ਨਿਰਬਿਖ ਬਿਅੰਤ। ੯੮।","roman":"Jih baran jaati nahee krit anant | aado apaar nirbikh biant | 98 |","meaning_en":"who has no varna or caste, of endless deeds, primal, boundless, free of poison, infinite.","page":825,"meaning_status":"draft","note":"ਨਿਰਬਿਖ: 'free of poison/evil'; uncertain."}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":825,"lines":[{"gurmukhi":"ਬਰਣੀ ਨ ਜਾਤਿ ਜਿਹ ਰੰਗ ਰੇਖ। ਅਤਭੁਤ ਅਨੰਤ ਅਤਿ ਬਲ ਅਭੇਖ।","roman":"Barnee na jaati jih rang rekh | atbhut anant ati bal abhekh |","meaning_en":"Whose colour and feature cannot be described, wondrous, endless, very mighty, without garb;","page":825,"meaning_status":"draft"},{"gurmukhi":"ਅਨਖੰਡ ਚਿਤ ਅਬਿਕਾਰ ਰੂਪ। ਦੇਵਾਨ ਦੇਵ ਮਹਿਮਾ ਅਨੂਪ। ੯੯।","roman":"Ankhand chit abikaar roop | devaan dev mahimaa anoop | 99 |","meaning_en":"of undivided mind, form without blemish, God of gods, of incomparable glory.","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":825,"lines":[{"gurmukhi":"ਉਸਤਤੀ ਨਿੰਦ ਜਿਹ ਇਕ ਸਮਾਨ। ਆਭਾ ਅਖੰਡ ਮਹਿਮਾ ਮਹਾਨ।","roman":"Usattee nind jih ik samaan | aabhaa akhand mahimaa mahaan |","meaning_en":"To whom praise and blame are alike, of undivided radiance and great glory;","page":825,"meaning_status":"draft"},{"gurmukhi":"ਅਬਿਕਾਰ ਚਿਤ ਅਨੁਭਵ ਪ੍ਰਕਾਸ। ਘਟਿ ਘਟਿ ਬਿਯਾਪ ਨਿਸ ਦਿਨ ਉਦਾਸ। ੧੦੦।","roman":"Abikaar chit anubhav prakaas | ghati ghati biyaap nis din udaas | 100 |","meaning_en":"of unblemished mind, light of experience, pervading every heart, detached night and day.\"","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":825,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਦਤ ਉਸਤਤਿ ਉਚਾਰ। ਡੰਡਵਤ ਕੀਨ ਅਤ੍ਰਿਜ ਉਦਾਰ।","roman":"Ih bhaati dat usatti uchaar | dandvat keen atrij udaar |","meaning_en":"In this way Datt uttered praise; the noble son of Atri prostrated himself,","page":825,"meaning_status":"draft"},{"gurmukhi":"ਅਰੁ ਭਾਤਿ ਭਾਤਿ ਉਠਿ ਪਰਤ ਚਰਨਿ। ਜਾਨੀ ਨ ਜਾਇ ਜਿਹ ਜਾਤਿ ਬਰਨ। ੧੦੧।","roman":"Aru bhaati bhaati uthi parat charni | jaanee na jaai jih jaati baran | 101 |","meaning_en":"and again and again rose and fell at the feet of Him whose caste and colour cannot be known.","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":825,"lines":[{"gurmukhi":"ਜਉ ਕਰੈ ਕ੍ਰਿਤ ਕਈ ਜੁਗ ਉਚਾਰ। ਨਹੀ ਤਦਿਪ ਤਾਸੁ ਲਹਿ ਜਾਤ ਪਾਰ।","roman":"Jau karai krit kaee jug uchaar | nahee tadip taasu lahi jaat paar |","meaning_en":"\"Though one tells His deeds for many ages, still one cannot reach His limit.","page":825,"meaning_status":"draft"},{"gurmukhi":"ਮਮ ਅਲਪ ਬੁਧਿ ਤਵ ਗੁਨ ਅਨੰਤ। ਬਰਨਾ ਨ ਜਾਤ ਤੁਮ ਅਤਿ ਬਿਅੰਤ। ੧੦੨।","roman":"Mam alap budhi tav gun anant | barnaa na jaat tum ati biant | 102 |","meaning_en":"My intellect is small, Your virtues endless; You cannot be described, You are utterly infinite.","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":825,"lines":[{"gurmukhi":"ਤਵ ਗੁਣ ਅਤਿ ਊਚ ਅੰਬਰ ਸਮਾਨ। ਮਮ ਅਲਪ ਬੁਧਿ ਬਾਲਕ ਅਜਾਨ।","roman":"Tav gun ati ooch anbar samaan | mam alap budhi baalak ajaan |","meaning_en":"Your virtues are high as the sky; my intellect is small, an ignorant child's.","page":825,"meaning_status":"draft"},{"gurmukhi":"ਕਿਮ ਸਕੌ ਬਰਨ ਤੁਮਰੇ ਪ੍ਰਭਾਵ। ਤਵ ਪਰਾ ਸਰਣਿ ਤਜਿ ਸਭ ਉਪਾਵ। ੧੦੩।","roman":"Kim sakau baran tumre prabhaav | tav paraa sarni taji sabh upaav | 103 |","meaning_en":"How can I describe Your power? I have fallen into Your refuge, abandoning all other means.","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":825,"lines":[{"gurmukhi":"ਜਿਹ ਲਖਤ ਚਤ੍ਰ ਨਹਿ ਭੇਦ ਬੇਦ। ਆਭਾ ਅਨੰਤ ਮਹਿਮਾ ਅਛੇਦ।","roman":"Jih lakhat chatr nahi bhed bed | aabhaa anant mahimaa achhed |","meaning_en":"Whose mystery the four Vedas do not perceive, of endless radiance and indivisible glory;","page":825,"meaning_status":"draft"},{"gurmukhi":"ਗੁਨ ਗਨਤ ਚਤ੍ਰ ਮੁਖ ਪਰਾ ਹਾਰ। ਤਬ ਨੇਤਿ ਨੇਤਿ ਕਿਨੇ ਉਚਾਰ। ੧੦੪।","roman":"Gun ganat chatr mukh paraa haar | tab neti neti kine uchaar | 104 |","meaning_en":"counting His virtues, the four-faced one (Brahma) was defeated, and then said 'not this, not this'.","page":825,"meaning_status":"draft"}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":826,"lines":[{"gurmukhi":"ਥਕਿ ਗਿਰਿਓ ਬ੍ਰਿਧ ਸਿਰ ਲਿਖਤ ਕਿਤ। ਚਕਿ ਰਹੇ ਬਾਲਿਖਿਲਾਦਿ ਚਿਤ।","roman":"Thaki girio bridh sir likhat kit | chaki rahe baalikhilaadi chit |","meaning_en":"The old one (Brahma) grew weary and fell, writing on heads; the Balkhilya sages and others were astonished in mind;","page":826,"meaning_status":"draft","note":"ਸਿਰ ਲਿਖਤ: Brahma writing destinies on foreheads; line uncertain."},{"gurmukhi":"ਗੁਨ ਗਨਤ ਚਤ੍ਰ ਮੁਖ ਹਾਰ ਮਾਨਿ। ਹਠਿ ਤਜਿ ਬਿਅੰਤਿ ਕਿਨੋ ਬਖਾਨ। ੧੦੫।","roman":"Gun ganat chatr mukh haar maani | hathi taji bianti kino bakhaan | 105 |","meaning_en":"counting His virtues, the four-faced one admitted defeat, and giving up obstinacy called Him infinite.","page":826,"flags":[{"code":"ੰੰ","reason":"same sign typed twice; written once (prints as one)"}],"meaning_status":"draft"}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":826,"lines":[{"gurmukhi":"ਤਹ ਜਪਤ ਰੁਦ੍ਰ ਜੁਗ ਕੋਟਿ ਭੀਤ। ਬਹਿ ਗਈ ਗੰਗ ਸਿਰ ਮੁਰਿ ਨ ਚੀਤ।","roman":"Tah japat rudr jug koti bheet | bahi gaee gang sir muri na cheet |","meaning_en":"There Rudra meditated for ten million ages; the Ganga flowed from his head, but his mind did not turn back;","page":826,"meaning_status":"draft","note":"ਮੁਰਿ ਨ ਚੀਤ: 'his mind did not waver'; uncertain."},{"gurmukhi":"ਕਈ ਕਲਪ ਬੀਤ ਜਿਹ ਧਰਤਿ ਧਿਆਨ। ਨਹੀ ਤਦਿਪ ਧਿਆਨ ਆਏ ਸੁਜਾਨ।੧੦੬।","roman":"Kaee kalap beet jih dharti dhiaan | nahee tadip dhiaan aae sujaan | 106 |","meaning_en":"many ages passed while he held meditation, yet still the Wise One did not come into his meditation.","page":826,"meaning_status":"draft"}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":826,"lines":[{"gurmukhi":"ਜਬ ਕੀਨ ਨਾਲਿ ਬ੍ਰਹਮਾ ਪ੍ਰਵੇਸ। ਮੁਨ ਮਨਿ ਮਹਾਨ ਦਿਜਬਰ ਦਿਜੇਸ।","roman":"Jab keen naali brahmaa praves | mun mani mahaan dijbar dijes |","meaning_en":"When Brahma entered the lotus stalk — the great jewel of sages, best of Brahmins, lord of the twice-born —","page":826,"meaning_status":"draft"},{"gurmukhi":"ਨਹੀ ਕਮਲ ਨਾਲ ਕੋ ਲਖਾ ਪਾਰ। ਕਹੋ ਤਾਸੁ ਕੈਸ ਪਾਵੈ ਬਿਚਾਰ। ੧੦੭।","roman":"Nahee kamal naal ko lakhaa paar | kaho taasu kais paavai bichaar | 107 |","meaning_en":"he could not find the end of the lotus stalk; say, how can he find Him by reflection?","page":826,"meaning_status":"draft"}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":826,"lines":[{"gurmukhi":"ਬਰਨੀ ਨ ਜਾਤਿ ਜਿਹ ਛਬਿ ਸੁਰੰਗ। ਆਭਾ ਆਪਾਰ ਮਹਿਮਾ ਅਭੰਗ।","roman":"Barnee na jaati jih chhabi surang | aabhaa aapaar mahimaa abhang |","meaning_en":"Whose fair beauty cannot be described, of boundless radiance and unbroken glory;","page":826,"meaning_status":"draft","note":"ਆਪਾਰ: printed so; read as apaar."},{"gurmukhi":"ਜਿਹ ਏਕ ਰੂਪ ਕਿਨੋ ਅਨੇਕ। ਪਗ ਛੋਰਿ ਆਨ ਤਿਹ ਧਰੋ ਟੇਕ। ੧੦੮।","roman":"Jih ek roop kino anek | pag chhori aan tih dharo tek | 108 |","meaning_en":"who made the one form into many — leaving all others, I have come and taken support at His feet.\"","page":826,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Ruaal metre.","page":826,"meaning_status":"draft"},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":826,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਿਅੰਤਿ ਦੇਸ ਭਵੰਤ ਕਿਰਤ ਉਚਾਰ।","roman":"Bhaati bhaati bianti des bhavant kirat uchaar |","meaning_en":"In many ways, wandering through endless lands, he uttered His praise;","page":826,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਪਗੋ ਲਗਾ ਤਜਿ ਗਰਬ ਅਤ੍ਰਿ ਕੁਮਾਰ।","roman":"Bhaati bhaati pago lagaa taji garab atri kumaar |","meaning_en":"in many ways the son of Atri fell at His feet, abandoning pride.","page":826,"meaning_status":"draft"},{"gurmukhi":"ਕੋਟਿ ਬਰਖ ਕਰੀ ਜਬੈ ਹਰਿ ਸੇਵਿ ਵਾ ਚਿਤੁ ਲਾਇ।","roman":"Koti barakh karee jabai hari sevi vaa chitu laai |","meaning_en":"When he had served Hari for ten million years with his mind fixed on Him,","page":826,"meaning_status":"draft"},{"gurmukhi":"ਅਕਸਮਾਤ ਭਈ ਤਬੈ ਤਿਹ ਬਿਓਮ ਬਾਨ ਬਨਾਇ। ੧੦੯।","roman":"Akasmaat bhaee tabai tih biom baan banaai | 109 |","meaning_en":"then suddenly a voice from the sky spoke to him.","page":826,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਬ੍ਯੋਮ ਬਾਨੀ ਬਾਚ ਦਤ ਪ੍ਰਤਿ","gurmukhi":"ਬ੍ਯੋਮ ਬਾਨੀ ਬਾਚ ਦਤ ਪ੍ਰਤਿ","roman":"Byom baanee baach dat prati","meaning_en":"The voice from the sky said to Datt:","page":826,"meaning_status":"draft"},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":826,"lines":[{"gurmukhi":"ਦਤ ਸਤਿ ਕਹੋ ਤੁਝੈ ਗੁਰ ਹੀਣ ਮੁਕਤਿ ਨ ਹੋਇ।","roman":"Dat sati kaho tujhai gur heen mukti na hoi |","meaning_en":"\"Datt, I tell you truly: without a guru there is no liberation.","page":826,"meaning_status":"draft"},{"gurmukhi":"ਰਾਵ ਰੰਕ ਪ੍ਰਜਾ ਵਜਾ ਇਮ ਭਾਖਈ ਸਭ ਕੋਇ।","roman":"Raav rank prajaa vajaa im bhaakhaee sabh koi |","meaning_en":"King and pauper, subjects and all, everyone says so.","page":826,"meaning_status":"draft","note":"ਵਜਾ: obscure; perhaps filler ('praja-vaja') or 'openly'; uncertain."},{"gurmukhi":"ਕੋਟਿ ਕਸਟ ਨ ਕਿਉ ਕਰੋ ਨਹੀ ਐਸ ਦੇਹਿ ਉਧਾਰ।","roman":"Koti kasat na kiu karo nahee ais dehi udhaar |","meaning_en":"Though you endure ten million hardships, there is no deliverance this way.","page":826,"meaning_status":"draft"},{"gurmukhi":"ਜਾਇ ਕੈ ਗੁਰ ਕੀਜੀਐ ਸੁਨਿ ਸਤਿ ਅਤ੍ਰਿ ਕੁਮਾਰ। ੧੧੦।","roman":"Jaai kai gur keejeeai suni sati atri kumaar | 110 |","meaning_en":"Go and take a guru; listen to the truth, son of Atri.\"","page":826,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਦਤ ਬਾਚ","gurmukhi":"ਦਤ ਬਾਚ","roman":"Dat baach","meaning_en":"Datt said:","page":826,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Ruaal metre.","page":826,"meaning_status":"draft"},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":826,"lines":[{"gurmukhi":"ਐਸ ਬਾਕ ਭਏ ਜਬੈ ਤਬ ਦਤ ਸਤ ਸਰੂਪ।","roman":"Ais baak bhae jabai tab dat sat saroop |","meaning_en":"When such words were spoken, then Datt, the very form of truth,","page":826,"meaning_status":"draft","note":"ਸਤ ਸਰੂਪ: 'form of truth' (or of goodness)."},{"gurmukhi":"ਸਿੰਧੁ ਸੀਲ ਸੁਬ੍ਰਿਤ ਕੋ ਨਦ ਗ੍ਯਾਨ ਕੋ ਜਨੁ ਕੂਪ।","roman":"Sindhu seel subrit ko nad gyaan ko janu koop |","meaning_en":"an ocean of good conduct and fine practice, as if a river or well of knowledge,","page":826,"meaning_status":"draft"},{"gurmukhi":"ਪਾਨ ਲਾਗ ਡੰਡੌਤਿ ਕੈ ਇਹ ਭਾਤਿ ਕੀਨ ਉਚਾਰ।","roman":"Paan laag dandauti kai ih bhaati keen uchaar |","meaning_en":"touched the feet and prostrated, and spoke thus:","page":826,"meaning_status":"draft"},{"gurmukhi":"ਕਉਨ ਸੋ ਗੁਰ ਕੀਜੀਐ ਕਹਿ ਮੋਹਿ ਤਤ ਬਿਚਾਰ। ੧੧੧।","roman":"Kaun so gur keejeeai kahi mohi tat bichaar | 111 |","meaning_en":"\"Whom should I take as guru? Tell me, considering the essence.\"","page":826,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਬ੍ਯੋਮ ਬਾਨੀ ਬਾਚ","gurmukhi":"ਬ੍ਯੋਮ ਬਾਨੀ ਬਾਚ","roman":"Byom baanee baach","meaning_en":"The voice from the sky said:","page":826,"meaning_status":"draft"},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":826,"lines":[{"gurmukhi":"ਜਉਨ ਚਿਤ ਬਿਖੈ ਰੁਚੈ ਸੋਈ ਕੀਜੀਐ ਗੁਰਦੇਵ।","roman":"Jaun chit bikhai ruchai soee keejeeai gurdev |","meaning_en":"\"Whoever pleases your mind, take him as your divine guru;","page":826,"meaning_status":"draft"},{"gurmukhi":"ਤਿਆਗ ਕਰਿ ਕੈ ਕਪਟ ਕਉ ਚਿਤ ਲਾਇ ਕੀਜੈ ਸੇਵ।","roman":"Tiaag kari kai kapat kau chit laai keejai sev |","meaning_en":"abandon deceit and serve him with your mind fixed.","page":826,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝ ਹੈ ਗੁਰਦੇਵ ਤਉ ਤੁਮ ਪਾਇ ਹੋ ਬਰੁ ਦਾਨ।","roman":"Reejh hai gurdev tau tum paai ho baru daan |","meaning_en":"When the divine guru is pleased, you will receive the gift of a boon;","page":826,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਨ ਹੋਇ ਉਧਾਰ ਪੈ ਸੁਨਿ ਲੇਹੁ ਦਤ ਸੁਜਾਨ। ੧੧੨।","roman":"Yau na hoi udhaar pai suni lehu dat sujaan | 112 |","meaning_en":"otherwise there is no deliverance — listen, wise Datt.\"","page":826,"meaning_status":"draft"}]},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":827,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਮੰਤ੍ਰ ਦਯੋ ਜਿਨੈ ਸੋਈ ਜਾਨਿ ਕੈ ਗੁਰਦੇਵ।","roman":"Pritham mantr dayo jinai soee jaani kai gurdev |","meaning_en":"Knowing as divine guru the One who first gave him the mantra,","page":827,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗ ਕਾਰਣ ਕੋ ਚਲਾ ਜੀਅ ਜਾਨਿ ਕੈ ਅਨਭੇਵ।","roman":"Jog kaaran ko chalaa jeea jaani kai anbhev |","meaning_en":"he set off for the sake of yoga, knowing in his heart the Mysterious One.","page":827,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਮਾਤ ਰਹੇ ਮਨੈ ਕਰਿ ਮਾਨ ਬੈਨ ਨ ਏਕ।","roman":"Taat maat rahe manai kari maan bain na ek |","meaning_en":"Father and mother tried to stop him, but he heeded not one word;","page":827,"meaning_status":"draft"},{"gurmukhi":"ਘੋਰ ਕਾਨਿਨ ਕੌ ਚਲਾ ਧਰਿ ਜੋਗਿ ਨ੍ਯਾਸ ਅਨੇਕ। ੧੧੩।","roman":"Ghor kaanin kau chalaa dhari jogi nyaas anek | 113 |","meaning_en":"he went to the dense forest, taking up many yogic practices.","page":827,"meaning_status":"draft","note":"ਨ੍ਯਾਸ: ritual placing (nyas) of mantras on the body; or 'renunciation'; uncertain."}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":827,"lines":[{"gurmukhi":"ਘੋਰ ਕਾਨਨਿ ਮੈ ਕਰੀ ਤਪਸਾ ਅਨੇਕ ਪ੍ਰਕਾਰ।","roman":"Ghor kaanni mai karee tapsaa anek prakaar |","meaning_en":"In the dense forest he did austerities of many kinds;","page":827,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿਨ ਕੇ ਕਰੇ ਇਕ ਚਿਤ ਮੰਤ੍ਰ ਉਚਾਰ।","roman":"Bhaati bhaatin ke kare ik chit mantr uchaar |","meaning_en":"with one-pointed mind he recited mantras of many kinds.","page":827,"meaning_status":"draft"},{"gurmukhi":"ਕਸਟ ਕੈ ਜਬ ਹੀ ਕੀਆ ਤਪ ਘੋਰ ਬਰਖ ਪ੍ਰਮਾਨ।","roman":"Kasat kai jab hee keeaa tap ghor barakh pramaan |","meaning_en":"When he had done severe austerity with hardship for many years,","page":827,"meaning_status":"draft"},{"gurmukhi":"ਬੁਧਿ ਕੋ ਬਰੁ ਦੇਤ ਭੇ ਤਬ ਆਨਿ ਬੁਧਿ ਨਿਧਾਨ। ੧੧੪।","roman":"Budhi ko baru det bhe tab aani budhi nidhaan | 114 |","meaning_en":"then the Treasury of Wisdom came and gave him the boon of wisdom.","page":827,"meaning_status":"draft"}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":827,"lines":[{"gurmukhi":"ਬੁਧਿ ਕੌ ਬਰੁ ਜਉ ਦਯੋ ਤਿਨ ਆਨ ਬੁਧ ਅਨੰਤ।","roman":"Budhi kau baru jau dayo tin aan budh anant |","meaning_en":"When the Infinite in wisdom came and gave him the boon of wisdom,","page":827,"meaning_status":"draft"},{"gurmukhi":"ਪਰਮ ਪੁਰੁਖ ਪਵਿਤ੍ਰ ਕੈ ਗਏ ਦਤ ਦੇਵ ਮਹੰਤ।","roman":"Param purukh pavitr kai gae dat dev mahant |","meaning_en":"having made the great Datt the divine pure, the Supreme Being went away.","page":827,"meaning_status":"draft"},{"gurmukhi":"ਅਕਸਮਾਤ੍ਰ ਬਢੀ ਤਬੈ ਬੁਧਿ ਜਤ੍ਰ ਤਤ੍ਰ ਦਿਸਾਨ।","roman":"Akasmaatr badhee tabai budhi jatr tatr disaan |","meaning_en":"Suddenly then his wisdom grew, seen everywhere;","page":827,"meaning_status":"draft"},{"gurmukhi":"ਧਰਮ ਪ੍ਰਚੁਰ ਕੀਆ ਜਹੀ ਤਹ ਪਰਮ ਪਾਪ ਖਿਸਾਨ। ੧੧੫।","roman":"Dharam prachur keeaa jahee tah param paap khisaan | 115 |","meaning_en":"he spread righteousness wherever he went, and great sin faded away.","page":827,"meaning_status":"draft","note":"ਖਿਸਾਨ: 'slipped away, was abashed'."}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":827,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਅਕਾਲ ਗੁਰੂ ਕੀਆ ਜਿਹ ਕੋ ਕਬੈ ਨਹੀ ਨਾਸ।","roman":"Pritham akaal guroo keeaa jih ko kabai nahee naas |","meaning_en":"First he took as guru the Timeless One, who is never destroyed,","page":827,"meaning_status":"draft"},{"gurmukhi":"ਜਤ੍ਰ ਤਤ੍ਰ ਦਿਸਾ ਵਿਸਾ ਜਿਹ ਠਉਰ ਸਰਬ ਨਿਵਾਸ।","roman":"Jatr tatr disaa visaa jih thaur sarab nivaas |","meaning_en":"who dwells here, there, in all directions and in every place,","page":827,"meaning_status":"draft","note":"ਦਿਸਾ ਵਿਸਾ: 'directions and intermediate directions'."},{"gurmukhi":"ਅੰਡ ਜੇਰਜ ਸੇਤ ਉਤਭੁਜ ਕੀਨ ਜਾਸ ਪਸਾਰ।","roman":"And jeraj set utbhuj keen jaas pasaar |","meaning_en":"who spread out the egg-born, womb-born, sweat-born and earth-born.","page":827,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹਿ ਜਾਨ ਗੁਰੂ ਕੀਯੋ ਮੁਨਿ ਸਤਿ ਦਤ ਸੁ ਧਾਰ। ੧੧੬।","roman":"Taahi jaan guroo keeyo muni sati dat su dhaar | 116 |","meaning_en":"Knowing Him, the sage, the true Datt, took Him as his guru.","page":827,"meaning_status":"draft","note":"ਸੁ ਧਾਰ: 'firmly, properly'."}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਦਤ ਮਹਾਤਮੇ ਪ੍ਰਥਮ ਗੁਰੂ ਅਕਾਲ ਪੁਰੁਖ ਸਮਾਪਤੰ। ੧।","roman":"Iti sree dat mahaatme pratham guroo akaal purukh samaaptan | 1 |","meaning_en":"Here ends, in the Glory of Sri Datt, the first guru, the Timeless Being. 1.","page":827,"meaning_status":"draft"}],"page":827,"number":[1]}});
